/// Stable schema for facade-level explanation records.
pub const EXPLAIN_SCHEMA_VERSION: u32 = 16;

// Automatic ordinary search admits exact anchors and staged general primaries
// when the finite incumbent cannot fit. Three-member primaries use memchr3;
// wider Four/Range/Set primaries use one compiler- or receipt-selected
// whole-slice member finder whenever that selection is vectorized. Raw
// Shift-And and scalar/direct candidate streams preserve K0. Construction
// proves a word width of at most 64, so one primary finder leaves at most 63 non-universal
// verification predicates. The retained second finder and final Shift-And
// handoff keep dense rejection streams inside the closed linear bound.
const FIXED_PREDICATE_SEARCH_AUTO_MAX_VERIFICATION_PREDICATES: usize =
    FIXED_PREDICATE_WORD64_MAX_WIDTH - 1;

/// Escapes all regular-expression meta characters in `pattern`.
///
/// The returned string is safe to use as a literal in a Rust-compatible
/// regular expression. Its behavior is pinned by FRE's exact
/// `regex-syntax` 0.8.11 dependency, which is also part of
/// [`RustProfile::regex_1_12_4`].
#[must_use]
pub fn escape(pattern: &str) -> String {
    regex_syntax::escape(pattern)
}

/// Construction limits whose identities affect admission or lowering.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct BuildLimits {
    /// Exact-upstream-pending strict mode or an explicitly FRE-quota mode.
    pub admission: AdmissionPolicy,
    /// Non-configurable-in-production hard syntax safety envelope.
    pub syntax_safety: SafetyEnvelope,
    /// Checked graph construction limits.
    pub lowering: LowerLimits,
    /// Persistent exact-literal kernel limit.
    pub literal: LiteralBuildLimits,
    /// Bounded DFA fallback for an exactly enumerated finite language.
    pub literal_set: LiteralSetBuildLimits,
    /// SIMD packed plan limits for an exactly enumerated finite language.
    pub packed_literal_set: PackedLiteralSetBuildLimits,
    /// Proof-restricted positive greedy `CLASS{min,max} SUFFIX` construction limits.
    pub required_literal: RequiredLiteralBuildLimits,
    /// Canonical `LITERAL? BYTE_CLASS+ LITERAL?` construction limits.
    pub literal_class_run_literal: LiteralClassRunLiteralBuildLimits,
    /// Ordered `LITERAL BYTE_CLASS+` alternative construction limits.
    pub prefix_class_alternation: PrefixClassAlternationBuildLimits,
    /// Unique-boundary `\A CLASS+ SUFFIX (?:\z)?` construction limits.
    pub forward_anchored: ForwardAnchoredBuildLimits,
    /// Maximum checked planner traversal/copy work.
    pub max_planner_work: u64,
    /// Maximum logical bytes retained by the published source, capture-name
    /// metadata and selected execution plan.
    pub max_persistent_bytes: usize,
}

impl Default for BuildLimits {
    fn default() -> Self {
        Self {
            admission: AdmissionPolicy::default(),
            syntax_safety: SafetyEnvelope::default(),
            lowering: LowerLimits::default(),
            literal: LiteralBuildLimits::default(),
            literal_set: LiteralSetBuildLimits::default(),
            packed_literal_set: PackedLiteralSetBuildLimits::default(),
            required_literal: RequiredLiteralBuildLimits::default(),
            literal_class_run_literal: LiteralClassRunLiteralBuildLimits::default(),
            prefix_class_alternation: PrefixClassAlternationBuildLimits::default(),
            forward_anchored: ForwardAnchoredBuildLimits::default(),
            max_planner_work: 8_000_000,
            max_persistent_bytes: 268_435_456,
        }
    }
}

/// A half-open byte match in the original haystack.
#[derive(Clone, Copy, Debug, Eq, Hash, PartialEq)]
pub struct Match {
    start: usize,
    end: usize,
}

impl Match {
    /// Inclusive byte start.
    #[must_use]
    pub const fn start(self) -> usize {
        self.start
    }

    /// Exclusive byte end.
    #[must_use]
    pub const fn end(self) -> usize {
        self.end
    }

    /// Whether the selected match consumed no bytes.
    #[must_use]
    pub const fn is_empty(self) -> bool {
        self.start == self.end
    }

    /// Number of matched bytes.
    #[must_use]
    pub const fn len(self) -> usize {
        self.end.saturating_sub(self.start)
    }

    /// Half-open byte range in the original haystack.
    #[must_use]
    pub const fn range(self) -> core::ops::Range<usize> {
        self.start..self.end
    }
}

/// A byte match that retains the exact original haystack it was selected from.
///
/// [`Match`] remains the small offset-only value used by accounting-oriented
/// APIs. This companion preserves the pinned Rust bytes API's borrowed-match
/// contract, including direct access to the matched bytes and lossless
/// conversion to either the bytes or their original range.
#[derive(Clone, Copy, Eq, Hash, PartialEq)]
pub struct ByteMatch<'h> {
    haystack: &'h [u8],
    span: Match,
}

impl<'h> ByteMatch<'h> {
    /// Inclusive byte start in the original haystack.
    #[must_use]
    pub const fn start(self) -> usize {
        self.span.start()
    }

    /// Exclusive byte end in the original haystack.
    #[must_use]
    pub const fn end(self) -> usize {
        self.span.end()
    }

    /// Whether the selected match consumed no bytes.
    #[must_use]
    pub const fn is_empty(self) -> bool {
        self.span.is_empty()
    }

    /// Number of matched bytes.
    #[must_use]
    pub const fn len(self) -> usize {
        self.span.len()
    }

    /// Half-open byte range in the original haystack.
    #[must_use]
    pub const fn range(self) -> core::ops::Range<usize> {
        self.span.range()
    }

    /// The exact bytes selected from the original haystack.
    #[must_use]
    pub fn as_bytes(&self) -> &'h [u8] {
        &self.haystack[self.span.range()]
    }
}

impl fmt::Debug for ByteMatch<'_> {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter
            .debug_struct("ByteMatch")
            .field("start", &self.start())
            .field("end", &self.end())
            .field("bytes", &DebugMatchBytes(self.as_bytes()))
            .finish()
    }
}

/// Pinned Rust-regex debug escaping for a byte match's selected haystack.
///
/// Valid UTF-8 is formatted like a Rust string while each byte that cannot be
/// decoded is emitted as a lower-case hexadecimal escape. Keeping this helper
/// private avoids adding a formatting type to the public compatibility
/// surface.
struct DebugMatchBytes<'a>(&'a [u8]);

impl fmt::Debug for DebugMatchBytes<'_> {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("\"")?;
        let mut bytes = self.0;
        while !bytes.is_empty() {
            match core::str::from_utf8(bytes) {
                Ok(valid) => {
                    write_debug_match_str(formatter, valid)?;
                    bytes = &[];
                }
                Err(error) => {
                    let valid_up_to = error.valid_up_to();
                    let valid = core::str::from_utf8(&bytes[..valid_up_to])
                        .expect("UTF-8 error's valid prefix must decode");
                    write_debug_match_str(formatter, valid)?;
                    write!(formatter, r"\x{:02x}", bytes[valid_up_to])?;
                    bytes = &bytes[valid_up_to.saturating_add(1)..];
                }
            }
        }
        formatter.write_str("\"")
    }
}

fn write_debug_match_str(formatter: &mut fmt::Formatter<'_>, valid: &str) -> fmt::Result {
    for character in valid.chars() {
        match character {
            '\0' => formatter.write_str("\\0")?,
            '\u{1}'..='\u{8}' | '\u{b}' | '\u{c}' | '\u{e}'..='\u{19}' | '\u{7f}' => {
                write!(formatter, "\\x{:02x}", u32::from(character))?;
            }
            _ => write!(formatter, "{}", character.escape_debug())?,
        }
    }
    Ok(())
}

impl<'h> From<ByteMatch<'h>> for &'h [u8] {
    fn from(matched: ByteMatch<'h>) -> Self {
        matched.as_bytes()
    }
}

impl From<ByteMatch<'_>> for core::ops::Range<usize> {
    fn from(matched: ByteMatch<'_>) -> Self {
        matched.range()
    }
}

/// Auditable construction facts for one portable plan.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct BuildReport {
    /// Complete compatibility profile selected before parsing.
    pub profile: CompatibilityProfile,
    /// What has and has not established constructor admission.
    pub admission: AdmissionStatus,
    /// Bounded syntax traversal facts.
    pub syntax: ParseSummary,
    /// Selected execution-plan family.
    pub plan: PlanKind,
    /// Checked planner traversal/copy work.
    pub planner_work: u64,
    /// Checked K0 lowering facts, absent for direct native finite-language plans.
    pub lowering: Option<LowerStats>,
    /// Immutable state count after independent automata validation.
    pub states: usize,
    /// Immutable edge count after independent automata validation.
    pub edges: usize,
    /// Immutable logical table payload bytes.
    pub plan_storage_bytes: usize,
    /// Exact retained bytes for the original pattern source.
    pub source_storage_bytes: usize,
    /// Exact logical heap bytes retained for indexed capture-name metadata.
    pub capture_name_storage_bytes: usize,
    /// Checked sum of source, capture-name and selected-plan logical bytes.
    pub charged_persistent_bytes: usize,
    /// Total persistent-byte ceiling enforced before publication.
    pub persistent_byte_limit: usize,
    /// Total capture slots, including the implicit whole-match slot.
    pub captures_len: usize,
    /// Capture slots present in every possible match, including the implicit
    /// whole-match slot, or `None` when participation cardinality can vary.
    pub static_captures_len: Option<usize>,
    /// Exact minimum bytes consumed by any match, or `None` if the HIR's
    /// language is empty. This is preserved for future aggregate routing.
    pub minimum_match_bytes: Option<usize>,
    /// Complete construction certificate for the classic
    /// `CLASS{min,max} SUFFIX` required-tail runtime. Other members of the
    /// broader [`PlanKind::RequiredLiteral`] family retain their own typed
    /// accounting and leave this field absent.
    pub required_literal: Option<RequiredLiteralBuildAccounting>,
    /// Complete construction certificate for the literal/class-run plan.
    pub literal_class_run_literal: Option<LiteralClassRunLiteralBuildAccounting>,
    /// Complete construction certificate for the forward-boundary plan.
    pub forward_anchored: Option<ForwardAnchoredBuildAccounting>,
}

/// An honestly labelled selected plan family.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum PlanKind {
    /// SIMD-aware shared native exact-substring primitive. This is not JIT.
    ExactLiteral,
    /// Shared native finite-literal primitive, including the fixed-column
    /// exact complete-word composition. This is not JIT.
    PackedLiteralSet,
    /// Bounded ordered finite-literal DFA used when packed search is ineligible.
    LiteralSetDfa,
    /// Proof-restricted required-tail native searches, including
    /// `CLASS{min,max} SUFFIX`, tail-head-disjoint nullable optional chains,
    /// bounded finite-token repetitions, and finite greedy universal-byte
    /// corridors. This is not JIT.
    RequiredLiteral,
    /// Canonical literal/class-run search backed by one native literal anchor.
    LiteralClassRunLiteral,
    /// Ordered alternatives of `UNICODE_CLASS+ LITERAL UNICODE_CLASS+`.
    ReverseInner,
    /// Ordered alternatives of `LITERAL BYTE_CLASS+` with two native anchors.
    PrefixClassAlternation,
    /// Operation-specialized root byte class repeated one or more times.
    PureByteClassRepeat,
    /// Finite positive greedy byte-class sequence with deterministic boundaries.
    BoundedByteClassSequence,
    /// Absolute-start unique-boundary forward scan. This is not JIT.
    ForwardAnchored,
    /// Generic bounded portable prioritized automaton.
    K0,
    /// Ordered Unicode simple-fold scalar sequences backed by a sparse trie.
    UnicodeFoldedLiteral,
    /// Linear ASCII or Unicode word-boundary class-run scan.
    UnicodeWordRun,
    /// Fixed-width Cartesian byte predicates backed by selective paired
    /// finders or one 64-bit Shift-And state.
    FixedPredicateWord64,
    /// Positive root Unicode scalar-class repetition with a bulk leading-byte
    /// filter and exact scalar verification.
    UnicodeScalarRun,
    /// Deterministic finite byte atoms over configured-byte or CRLF line domains.
    LineDomainByteAtoms,
}

/// Construction failure without semantic fallback.
#[derive(Debug)]
#[non_exhaustive]
pub enum BuildError {
    /// Syntax/profile/admission failure.
    Syntax(fre_syntax::ParseError),
    /// The syntax was valid but is outside the certified portable lowering.
    Lower(fre_lower::LowerError),
    /// Operation-specific kernel construction failure.
    Literal(LiteralError),
    /// Ordered finite-literal DFA construction failure.
    LiteralSet(LiteralSetError),
    /// Required-literal proof or construction failure.
    RequiredLiteral(RequiredLiteralBuildError),
    /// Literal/class-run proof revalidation or construction failure.
    LiteralClassRunLiteral(LiteralClassRunLiteralBuildError),
    /// Reverse-inner proof revalidation or construction failure.
    ReverseInner(ReverseInnerBuildError),
    /// Two-branch prefix/class proof revalidation or construction failure.
    PrefixClassAlternation(PrefixClassAlternationBuildError),
    /// A forced required-literal request did not have the exact HIR shape.
    RequiredLiteralShape,
    /// Forward-anchored proof or construction failure.
    ForwardAnchored(ForwardAnchoredBuildError),
    /// A forced forward-anchored request did not have the exact HIR shape.
    ForwardAnchoredShape,
    /// Checked planner work was exhausted before plan selection.
    PlannerWorkLimit { needed: u64, limit: u64 },
    /// Persistent-byte accounting overflowed `usize`.
    PersistentBytesOverflow,
    /// The completed matcher exceeded the total persistent-byte ceiling.
    PersistentBytesLimit { needed: usize, limit: usize },
    /// A planner buffer could not be reserved.
    AllocationFailed {
        structure: &'static str,
        additional: usize,
    },
    /// Internal facade/profile mismatch.
    InternalInvariant(&'static str),
}

/// Stable top-level classification for a failed portable construction.
///
/// This is deliberately coarser than [`BuildError`]. It lets conformance
/// adapters distinguish an upstream-invalid pattern from an FRE capability
/// gap, an explicitly configured resource refusal, invalid profile state, or
/// an internal construction failure without parsing diagnostic text.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum BuildFailureClass {
    /// The pinned syntax front-end rejected the pattern or its encoding.
    ExpectedInvalid,
    /// The pattern is valid but outside the currently certified executor.
    Unsupported,
    /// A checked caller-configured construction bound was exceeded.
    ResourceLimit,
    /// The requested compatibility profile or builder configuration is invalid.
    InvalidConfiguration,
    /// Allocation, arithmetic, emitted-plan, or facade invariants failed.
    InternalFailure,
}

impl BuildError {
    /// Classify this failure without inspecting its human-readable message.
    #[must_use]
    pub fn failure_class(&self) -> BuildFailureClass {
        match self {
            Self::Syntax(error) => match &error.category {
                fre_syntax::ErrorCategory::InvalidPatternEncoding
                | fre_syntax::ErrorCategory::UpstreamRustSyntax
                | fre_syntax::ErrorCategory::UpstreamRustCompiledTooBig { .. }
                | fre_syntax::ErrorCategory::Re2Syntax { .. } => BuildFailureClass::ExpectedInvalid,
                fre_syntax::ErrorCategory::FreResourceLimit { .. }
                | fre_syntax::ErrorCategory::StrictQualificationFailure { .. } => {
                    BuildFailureClass::ResourceLimit
                }
                fre_syntax::ErrorCategory::UnsupportedNotYetImplemented { .. } => {
                    BuildFailureClass::Unsupported
                }
                fre_syntax::ErrorCategory::InvalidConfiguration => {
                    BuildFailureClass::InvalidConfiguration
                }
            },
            Self::Lower(error) => lower_failure_class(error),
            Self::Literal(error) => match error {
                LiteralError::NeedleLimit { .. } | LiteralError::LinearTermLimit { .. } => {
                    BuildFailureClass::ResourceLimit
                }
                _ => BuildFailureClass::InternalFailure,
            },
            Self::LiteralSet(error) => match error {
                LiteralSetError::PatternLimit { .. }
                | LiteralSetError::PatternBytesLimit { .. }
                | LiteralSetError::BuildWorkLimit { .. }
                | LiteralSetError::BuildBytesLimit { .. }
                | LiteralSetError::PersistentBytesLimit { .. }
                | LiteralSetError::TransitionLimit { .. } => BuildFailureClass::ResourceLimit,
                _ => BuildFailureClass::InternalFailure,
            },
            Self::RequiredLiteral(error) => required_literal_failure_class(error),
            Self::LiteralClassRunLiteral(error) => literal_class_run_literal_failure_class(error),
            Self::ReverseInner(error) => reverse_inner_failure_class(error),
            Self::PrefixClassAlternation(error) => prefix_class_alternation_failure_class(error),
            Self::RequiredLiteralShape | Self::ForwardAnchoredShape => {
                BuildFailureClass::Unsupported
            }
            Self::ForwardAnchored(error) => forward_anchored_failure_class(error),
            Self::PlannerWorkLimit { .. } | Self::PersistentBytesLimit { .. } => {
                BuildFailureClass::ResourceLimit
            }
            Self::PersistentBytesOverflow
            | Self::AllocationFailed { .. }
            | Self::InternalInvariant(_) => BuildFailureClass::InternalFailure,
        }
    }
}

fn lower_failure_class(error: &fre_lower::LowerError) -> BuildFailureClass {
    match error {
        fre_lower::LowerError::Unsupported(_) => BuildFailureClass::Unsupported,
        fre_lower::LowerError::ResourceLimit { .. }
        | fre_lower::LowerError::Automata(fre_automata::CompileError::ResourceLimit { .. }) => {
            BuildFailureClass::ResourceLimit
        }
        _ => BuildFailureClass::InternalFailure,
    }
}

fn required_literal_failure_class(error: &RequiredLiteralBuildError) -> BuildFailureClass {
    if error.is_semantic_refusal() {
        return BuildFailureClass::Unsupported;
    }
    match error {
        RequiredLiteralBuildError::SuffixLimit { .. }
        | RequiredLiteralBuildError::WorkLimit { .. }
        | RequiredLiteralBuildError::ScratchLimit { .. }
        | RequiredLiteralBuildError::PersistentLimit { .. }
        | RequiredLiteralBuildError::PeakLimit { .. } => BuildFailureClass::ResourceLimit,
        _ => BuildFailureClass::InternalFailure,
    }
}

fn literal_class_run_literal_failure_class(
    error: &LiteralClassRunLiteralBuildError,
) -> BuildFailureClass {
    match error {
        LiteralClassRunLiteralBuildError::LiteralBytesLimit { .. }
        | LiteralClassRunLiteralBuildError::ClassRangesLimit { .. }
        | LiteralClassRunLiteralBuildError::ClassMembersLimit { .. }
        | LiteralClassRunLiteralBuildError::WorkLimit { .. }
        | LiteralClassRunLiteralBuildError::ScratchLimit { .. }
        | LiteralClassRunLiteralBuildError::PersistentLimit { .. }
        | LiteralClassRunLiteralBuildError::PeakLimit { .. } => BuildFailureClass::ResourceLimit,
        LiteralClassRunLiteralBuildError::MissingLiteralAnchor
        | LiteralClassRunLiteralBuildError::EmptyPrefix
        | LiteralClassRunLiteralBuildError::NonEmptyPrefixForCompleteAsciiWordRun
        | LiteralClassRunLiteralBuildError::EmptySuffix
        | LiteralClassRunLiteralBuildError::EmptyClass
        | LiteralClassRunLiteralBuildError::NonCanonicalClass
        | LiteralClassRunLiteralBuildError::UnsupportedUnicodeClass
        | LiteralClassRunLiteralBuildError::NonAsciiUnicodeLiteral
        | LiteralClassRunLiteralBuildError::PrefixBoundaryInClass
        | LiteralClassRunLiteralBuildError::SuffixBoundaryInClass
        | LiteralClassRunLiteralBuildError::InexactAsciiWordClass
        | LiteralClassRunLiteralBuildError::SuffixByteOutsideAsciiWordClass
        | LiteralClassRunLiteralBuildError::UnsupportedSearchMinimum
        | LiteralClassRunLiteralBuildError::InvalidFiniteBounds { .. }
        | LiteralClassRunLiteralBuildError::ClassOutsideAsciiWord
        | LiteralClassRunLiteralBuildError::SuffixByteOutsideAsciiWord => {
            BuildFailureClass::Unsupported
        }
        LiteralClassRunLiteralBuildError::AllocationFailed { .. }
        | LiteralClassRunLiteralBuildError::ArithmeticOverflow { .. } => {
            BuildFailureClass::InternalFailure
        }
        _ => BuildFailureClass::InternalFailure,
    }
}

fn reverse_inner_failure_class(error: &ReverseInnerBuildError) -> BuildFailureClass {
    match error {
        ReverseInnerBuildError::SourceRangesLimit { .. }
        | ReverseInnerBuildError::TooManyLiterals { .. }
        | ReverseInnerBuildError::LiteralBytesLimit { .. }
        | ReverseInnerBuildError::TotalLiteralBytesLimit { .. }
        | ReverseInnerBuildError::WorkLimit { .. }
        | ReverseInnerBuildError::ScratchLimit { .. }
        | ReverseInnerBuildError::PersistentLimit { .. }
        | ReverseInnerBuildError::PeakLimit { .. } => BuildFailureClass::ResourceLimit,
        ReverseInnerBuildError::EmptyClass
        | ReverseInnerBuildError::ReversedRange { .. }
        | ReverseInnerBuildError::NonCanonicalRanges
        | ReverseInnerBuildError::EmptyLiteralSet
        | ReverseInnerBuildError::EmptyLiteral { .. }
        | ReverseInnerBuildError::NonAsciiLiteral { .. }
        | ReverseInnerBuildError::LiteralScalarOutsideClass { .. } => {
            BuildFailureClass::Unsupported
        }
        ReverseInnerBuildError::AllocationFailed { .. }
        | ReverseInnerBuildError::ArithmeticOverflow { .. } => BuildFailureClass::InternalFailure,
        _ => BuildFailureClass::InternalFailure,
    }
}

fn prefix_class_alternation_failure_class(
    error: &PrefixClassAlternationBuildError,
) -> BuildFailureClass {
    match error {
        PrefixClassAlternationBuildError::ShapeLimit { .. }
        | PrefixClassAlternationBuildError::WorkLimit { .. }
        | PrefixClassAlternationBuildError::ScratchLimit { .. }
        | PrefixClassAlternationBuildError::PersistentLimit { .. }
        | PrefixClassAlternationBuildError::PeakLimit { .. } => BuildFailureClass::ResourceLimit,
        PrefixClassAlternationBuildError::EmptyPrefix { .. }
        | PrefixClassAlternationBuildError::SelfOverlappingPrefix { .. }
        | PrefixClassAlternationBuildError::EmptyClass { .. }
        | PrefixClassAlternationBuildError::NonCanonicalClass { .. }
        | PrefixClassAlternationBuildError::RunScannerDispatchUnavailable
        | PrefixClassAlternationBuildError::NonAsciiRunScannerClass { .. } => {
            BuildFailureClass::Unsupported
        }
        PrefixClassAlternationBuildError::RunScannerAllocationFailed { .. }
        | PrefixClassAlternationBuildError::AllocationFailed { .. }
        | PrefixClassAlternationBuildError::ArithmeticOverflow { .. } => {
            BuildFailureClass::InternalFailure
        }
        _ => BuildFailureClass::InternalFailure,
    }
}

fn forward_anchored_failure_class(error: &ForwardAnchoredBuildError) -> BuildFailureClass {
    if error.is_semantic_refusal() {
        return BuildFailureClass::Unsupported;
    }
    match error {
        ForwardAnchoredBuildError::SuffixLimit { .. }
        | ForwardAnchoredBuildError::WorkLimit { .. }
        | ForwardAnchoredBuildError::ScratchLimit { .. }
        | ForwardAnchoredBuildError::PersistentLimit { .. }
        | ForwardAnchoredBuildError::PeakLimit { .. } => BuildFailureClass::ResourceLimit,
        _ => BuildFailureClass::InternalFailure,
    }
}

fn unicode_folded_literal_resource_refusal(error: &UnicodeFoldedLiteralBuildError) -> bool {
    matches!(
        error,
        UnicodeFoldedLiteralBuildError::Resource { .. }
            | UnicodeFoldedLiteralBuildError::Trie(
                fre_kernels::FoldedLiteralTrieBuildError::Resource { .. }
            )
    )
}

fn map_unicode_folded_literal_build_error(error: UnicodeFoldedLiteralBuildError) -> BuildError {
    match error {
        UnicodeFoldedLiteralBuildError::Syntax(error) => BuildError::Syntax(error.into_source()),
        UnicodeFoldedLiteralBuildError::AllocationFailed { structure, items } => {
            BuildError::AllocationFailed {
                structure,
                additional: items,
            }
        }
        UnicodeFoldedLiteralBuildError::Trie(
            fre_kernels::FoldedLiteralTrieBuildError::AllocationFailed { structure, items },
        ) => BuildError::AllocationFailed {
            structure,
            additional: items,
        },
        UnicodeFoldedLiteralBuildError::Invariant { detail }
        | UnicodeFoldedLiteralBuildError::Trie(
            fre_kernels::FoldedLiteralTrieBuildError::Invariant { detail },
        ) => BuildError::InternalInvariant(detail),
        UnicodeFoldedLiteralBuildError::ArithmeticOverflow { computation }
        | UnicodeFoldedLiteralBuildError::Trie(
            fre_kernels::FoldedLiteralTrieBuildError::ArithmeticOverflow { computation },
        ) => BuildError::InternalInvariant(computation),
        UnicodeFoldedLiteralBuildError::Resource { .. }
        | UnicodeFoldedLiteralBuildError::Trie(
            fre_kernels::FoldedLiteralTrieBuildError::Resource { .. },
        ) => BuildError::InternalInvariant(
            "folded-literal resource refusal escaped optional Auto routing",
        ),
        UnicodeFoldedLiteralBuildError::Trie(_) => {
            BuildError::InternalInvariant("folded-literal trie returned an unknown failure")
        }
    }
}

fn charge_unicode_folded_planner_work(
    incumbent: u64,
    completed: usize,
    limit: u64,
) -> Result<u64, BuildError> {
    let folded = u64::try_from(completed).map_err(|_| {
        BuildError::InternalInvariant("folded-literal planner work does not fit u64")
    })?;
    let needed = incumbent
        .checked_add(folded)
        .ok_or(BuildError::InternalInvariant(
            "cumulative folded-literal planner work overflowed u64",
        ))?;
    if needed > limit {
        return Err(BuildError::PlannerWorkLimit { needed, limit });
    }
    Ok(needed)
}

const K0_NEGATIVE_PREFILTER_MIN_NEEDLE_BYTES: usize = 1;
const K0_MANDATORY_SUFFIX_MIN_NEEDLE_BYTES: usize = 3;
const K0_NEGATIVE_PREFILTER_MAX_NEEDLE_BYTES: usize = 1_024;
// The allocation-free HIR proof is speculative. This independent ceiling
// admits far more universal byte runs than ordinary syntax produces while
// preserving planner budget for the broader graph and reverse-inner routes
// after a late semantic refusal.
const K0_UNIVERSAL_FINITE_GREEDY_CORRIDOR_MAX_WORK: u64 = 262_144;
// The allocation-free reverse-suffix source-order proof is likewise optional.
// Bound its HIR walk independently so a semantically difficult prefix cannot
// consume the planner budget reserved for later general sidecars.
const K0_REVERSE_SUFFIX_SPAN_MAX_WORK: u64 = 262_144;
// Mandatory-cut materialization charges one operation per bitmap word read,
// byte-domain membership test, retained byte write and final inline plan.
const K0_MANDATORY_CUT_CARDINALITY_WORK: u64 = 4;
const K0_MANDATORY_CUT_BYTE_ENUMERATION_WORK: u64 = 256;
const K0_MANDATORY_CUT_PLAN_CONSTRUCTION_WORK: u64 = 1;

#[derive(Clone, Copy, Debug)]
struct K0MandatoryCutPlan {
    candidate: MandatoryCutCandidate,
    bytes: [u8; 3],
    count: u8,
}

impl K0MandatoryCutPlan {
    fn try_from_candidate(
        candidate: MandatoryCutCandidate,
        planner_work: &mut u64,
        max_planner_work: u64,
    ) -> Result<Option<Self>, BuildError> {
        if !try_charge_k0_mandatory_cut_work(
            planner_work,
            K0_MANDATORY_CUT_CARDINALITY_WORK,
            max_planner_work,
        )? {
            return Ok(None);
        }
        let cardinality = usize::from(candidate.byte_class().cardinality());
        if !(1..=3).contains(&cardinality) {
            return Ok(None);
        }
        let retained_byte_work = u64::try_from(cardinality).map_err(|_| {
            BuildError::InternalInvariant("K0 mandatory-cut cardinality does not fit planner work")
        })?;
        let construction_work = K0_MANDATORY_CUT_BYTE_ENUMERATION_WORK
            .checked_add(retained_byte_work)
            .and_then(|work| work.checked_add(K0_MANDATORY_CUT_PLAN_CONSTRUCTION_WORK))
            .ok_or(BuildError::InternalInvariant(
                "K0 mandatory-cut construction work overflowed",
            ))?;
        // Precharge the complete fixed-domain scan, retained-byte writes and
        // final inline plan construction. A refusal therefore publishes no
        // partially enumerated sidecar and leaves only completed work charged.
        if !try_charge_k0_mandatory_cut_work(
            planner_work,
            construction_work,
            max_planner_work,
        )? {
            return Ok(None);
        }
        let mut bytes = [0_u8; 3];
        let mut count = 0usize;
        for byte in u8::MIN..=u8::MAX {
            if candidate.byte_class().contains(byte) {
                *bytes.get_mut(count).ok_or(BuildError::InternalInvariant(
                    "eligible K0 mandatory-cut class exceeded inline storage",
                ))? = byte;
                count = count.checked_add(1).ok_or(BuildError::InternalInvariant(
                    "K0 mandatory-cut cardinality overflowed",
                ))?;
            }
        }
        if count != cardinality {
            return Err(BuildError::InternalInvariant(
                "K0 mandatory-cut enumeration disagreed with its cardinality",
            ));
        }
        Ok(Some(Self {
            candidate,
            bytes,
            count: u8::try_from(count).map_err(|_| {
                BuildError::InternalInvariant("K0 mandatory-cut cardinality does not fit u8")
            })?,
        }))
    }

    fn first_member(self, haystack: &[u8]) -> Option<usize> {
        debug_assert_eq!(
            usize::from(self.candidate.byte_class().cardinality()),
            usize::from(self.count)
        );
        match self.count {
            1 => memchr(self.bytes[0], haystack),
            2 => memchr2(self.bytes[0], self.bytes[1], haystack),
            3 => memchr3(self.bytes[0], self.bytes[1], self.bytes[2], haystack),
            _ => None,
        }
    }

    fn candidate_floor(self, window_start: usize, first_member: usize) -> Option<usize> {
        let MaximumConsumedDistance::Finite(maximum_before_root) =
            self.candidate.maximum_before_root()
        else {
            return None;
        };
        let first_member = window_start.checked_add(first_member)?;
        let maximum_before_root =
            usize::try_from(maximum_before_root).unwrap_or(usize::MAX);
        // If a selected match starts at s and consumes its mandatory-cut
        // byte at c, then c - s <= M. The first class member p is no later
        // than c, so p - M <= s; saturation only weakens that lower bound.
        Some(
            first_member
                .saturating_sub(maximum_before_root)
                .max(window_start),
        )
    }

    /// Earliest possible start of the terminal suffix after the first member
    /// of this mandatory class was found. The mandatory byte is either before
    /// the suffix, or occupies a suffix offset no smaller than the first class
    /// member in `literal`; either case yields this conservative floor.
    fn mandatory_suffix_candidate_floor(
        self,
        window_start: usize,
        first_member: usize,
        literal: &[u8],
    ) -> Option<usize> {
        let members = &self.bytes[..usize::from(self.count)];
        let first_member = window_start.checked_add(first_member)?;
        match literal.iter().position(|byte| members.contains(byte)) {
            Some(first_offset) => Some(first_member.saturating_sub(first_offset).max(window_start)),
            None => first_member.checked_add(1),
        }
    }

    const fn maximum_before_root(self) -> MaximumConsumedDistance {
        self.candidate.maximum_before_root()
    }

    fn cardinality(self) -> usize {
        usize::from(self.count)
    }

    #[cfg(test)]
    const fn bytes(self) -> ([u8; 3], u8) {
        (self.bytes, self.count)
    }
}

fn try_charge_k0_mandatory_cut_work(
    work: &mut u64,
    amount: u64,
    limit: u64,
) -> Result<bool, BuildError> {
    let needed = work.checked_add(amount).ok_or(BuildError::InternalInvariant(
        "K0 mandatory-cut planner work overflowed",
    ))?;
    if needed > limit {
        return Ok(false);
    }
    *work = needed;
    Ok(true)
}

struct K0MandatoryCutBuild<'a> {
    plan: Option<K0MandatoryCutPlan>,
    planner_work: u64,
    analysis_work: u64,
    frontier_continuation: Option<MandatoryCutContinuation<'a>>,
    storage_bytes: usize,
}

fn try_build_k0_mandatory_cut<'a>(
    raw: &'a fre_automata::RawPlan,
    limits: BuildLimits,
    incumbent_planner_work: u64,
) -> Result<K0MandatoryCutBuild<'a>, BuildError> {
    let remaining_work = limits
        .max_planner_work
        .checked_sub(incumbent_planner_work)
        .ok_or(BuildError::InternalInvariant(
            "incumbent planner work exceeded its enforced limit",
        ))?;
    if remaining_work == 0 {
        return Ok(K0MandatoryCutBuild {
            plan: None,
            planner_work: incumbent_planner_work,
            analysis_work: 0,
            frontier_continuation: None,
            storage_bytes: 0,
        });
    }
    let mut analysis_limits = MandatoryCutAnalysisLimits::default();
    analysis_limits.max_work = analysis_limits.max_work.min(remaining_work);
    analysis_limits.max_allocation_items = analysis_limits
        .max_allocation_items
        .min(limits.lowering.max_stack_items);
    let analysis = fre_automata::analyze_mandatory_cut_continuation(raw, analysis_limits);
    let stats = analysis.stats();
    if !stats.closes(analysis_limits) {
        return Err(BuildError::InternalInvariant(
            "K0 mandatory-cut analysis receipt did not close",
        ));
    }
    let mut planner_work = incumbent_planner_work
        .checked_add(stats.work())
        .ok_or(BuildError::InternalInvariant(
            "cumulative K0 mandatory-cut planner work overflowed u64",
        ))?;
    if planner_work > limits.max_planner_work {
        return Err(BuildError::InternalInvariant(
            "K0 mandatory-cut analysis exceeded its admitted planner work",
        ));
    }
    let (candidate, continuation) = match analysis {
        MandatoryCutContinuationAnalysis::Complete(continuation) => {
            (continuation.candidate(), Some(continuation))
        }
        MandatoryCutContinuationAnalysis::Declined(decline) => match decline.reason() {
            MandatoryCutDeclineReason::Resource {
                resource:
                    MandatoryCutResource::Work
                    | MandatoryCutResource::AllocationItems
                    | MandatoryCutResource::AllocationAttempts,
                ..
            }
            | MandatoryCutDeclineReason::Allocation { .. } => (None, None),
            MandatoryCutDeclineReason::MalformedGraph(_)
            | MandatoryCutDeclineReason::ArithmeticOverflow { .. }
            | MandatoryCutDeclineReason::InternalInvariant { .. } => {
                return Err(BuildError::InternalInvariant(
                    "lowered K0 graph failed mandatory-cut analysis",
                ));
            }
            _ => {
                return Err(BuildError::InternalInvariant(
                    "K0 mandatory-cut analysis returned an unknown decline",
                ));
            }
        },
    };
    // The optional frontier can only publish for a four-to-thirty-two-byte
    // mandatory root. Preserve both that scalar fact and the one-shot,
    // raw-plan-bound continuation from this already-charged exact-graph
    // receipt. Ineligible plans retain neither; eligible plans can enumerate
    // their frontier later, after the incumbent suffix has first refusal,
    // without replaying dominator and distance analysis. Displacement remains
    // a later concern because the HIR can supply a finite global bound when
    // the graph distance proof is conservatively unbounded.
    let packed_frontier_eligible = candidate.is_some_and(|candidate| {
        let cardinality = usize::from(candidate.byte_class().cardinality());
        cardinality > 3
            && cardinality
                <= fre_automata::MAX_MANDATORY_LITERAL_FRONTIER_ROOT_BYTES
    });
    let plan = match candidate {
        Some(candidate) => K0MandatoryCutPlan::try_from_candidate(
            candidate,
            &mut planner_work,
            limits.max_planner_work,
        )?,
        None => None,
    };
    Ok(K0MandatoryCutBuild {
        storage_bytes: plan.map_or(0, |_| core::mem::size_of::<K0MandatoryCutPlan>()),
        plan,
        planner_work,
        analysis_work: stats.work(),
        frontier_continuation: if packed_frontier_eligible {
            continuation
        } else {
            None
        },
    })
}

// This replacement scans only reusable windows large enough to amortize its
// immutable graph-to-frontier displacement. The overlap is the farthest
// possible root position plus the bytes needed to finish the longest packed
// literal. The universal floor remains unchanged for every fallback. A
// validated expensive fallback can reduce only the four-overlap margin by an
// immutable structural scale, but never below one complete overlap or the
// packed engine's SIMD minimum. Source contents never decide whether a call
// begins the packed route.
const K0_PACKED_FRONTIER_MIN_WINDOW_BYTES: usize = 1_024;
const K0_PACKED_FRONTIER_OVERLAP_FACTOR: usize = 4;

fn k0_packed_frontier_incremental_fallback_work(
    automaton: &Automaton,
    simd_minimum_haystack_bytes: usize,
) -> Option<u64> {
    if simd_minimum_haystack_bytes == 0 {
        return None;
    }
    // Subtracting the zero-byte certificate removes cold start-proof work.
    // The remainder is exactly the validated bound's monotone input term for
    // one packed SIMD-admissible quantum of this immutable fallback graph.
    let fixed = automaton.conservative_transition_work_bound(0).ok()?;
    automaton
        .conservative_transition_work_bound(simd_minimum_haystack_bytes)
        .ok()?
        .checked_sub(fixed)
}

fn k0_packed_frontier_amortization_scale(incremental_fallback_work: Option<u64>) -> usize {
    let baseline = u64::try_from(K0_PACKED_FRONTIER_MIN_WINDOW_BYTES).unwrap_or(u64::MAX);
    let Some(work) = incremental_fallback_work else {
        return 1;
    };
    let rounded = work.div_ceil(baseline).max(1);
    usize::try_from(rounded).unwrap_or(usize::MAX)
}

fn k0_packed_frontier_div_ceil(value: usize, divisor: usize) -> usize {
    value.div_ceil(divisor)
}

fn k0_packed_frontier_minimum_window_bytes(
    simd_minimum_haystack_bytes: usize,
    overlap_bytes: usize,
    overlap_admission_bytes: usize,
    incremental_fallback_work: Option<u64>,
) -> usize {
    let scale = k0_packed_frontier_amortization_scale(incremental_fallback_work);
    simd_minimum_haystack_bytes
        .max(overlap_bytes)
        .max(K0_PACKED_FRONTIER_MIN_WINDOW_BYTES)
        .max(k0_packed_frontier_div_ceil(
            overlap_admission_bytes,
            scale,
        ))
}

#[derive(Debug)]
struct K0PackedFrontierPlan {
    packed: PackedLiteralSetPlan,
    automaton_identity: u64,
    maximum_before_root: usize,
    minimum_window_bytes: usize,
}

impl K0PackedFrontierPlan {
    fn bind_automaton(&mut self, automaton: &Automaton) -> Result<(), BuildError> {
        if self.automaton_identity != 0 {
            return Err(BuildError::InternalInvariant(
                "K0 packed frontier was bound more than once",
            ));
        }
        let packed_build = self.packed.build_accounting();
        let overlap_bytes = self
            .maximum_before_root
            .checked_add(packed_build.max_pattern_bytes.saturating_sub(1))
            .expect("a published K0 packed frontier proved its overlap");
        let overlap_admission_bytes = overlap_bytes
            .checked_mul(K0_PACKED_FRONTIER_OVERLAP_FACTOR)
            .expect("a published K0 packed frontier proved its admission margin");
        let incremental_fallback_work = k0_packed_frontier_incremental_fallback_work(
            automaton,
            packed_build.simd_minimum_haystack_bytes,
        );
        self.minimum_window_bytes = k0_packed_frontier_minimum_window_bytes(
            packed_build.simd_minimum_haystack_bytes,
            overlap_bytes,
            overlap_admission_bytes,
            incremental_fallback_work,
        );
        self.automaton_identity = automaton.identity();
        Ok(())
    }

    const fn is_bound_to(&self, automaton: &Automaton) -> bool {
        self.automaton_identity != 0 && self.automaton_identity == automaton.identity()
    }

    fn storage_bytes(&self) -> usize {
        core::mem::size_of::<Self>()
            .checked_add(self.packed.build_accounting().persistent_bytes)
            .expect("a published K0 packed frontier proved its owner storage")
    }

    fn minimum_useful_progress_bytes(&self) -> usize {
        let packed_build = self.packed.build_accounting();
        let overlap_bytes = self
            .maximum_before_root
            .checked_add(packed_build.max_pattern_bytes.saturating_sub(1))
            .expect("a published K0 packed frontier proved its overlap");
        K0_PACKED_FRONTIER_MIN_WINDOW_BYTES
            .max(packed_build.simd_minimum_haystack_bytes)
            .max(overlap_bytes)
    }
}

struct K0PackedFrontierBuild {
    plan: Option<Box<K0PackedFrontierPlan>>,
    planner_work: u64,
    storage_bytes: usize,
}

fn k0_packed_frontier_maximum_before_root(
    graph_maximum: MaximumConsumedDistance,
    maximum_match_bytes: Option<usize>,
) -> Option<usize> {
    match graph_maximum {
        MaximumConsumedDistance::Finite(maximum) => usize::try_from(maximum).ok(),
        // Every byte before the mandatory root belongs to the selected match,
        // so a finite whole-match maximum is a conservative upper bound even
        // when the graph distance analysis cannot prove its tighter value.
        MaximumConsumedDistance::Unbounded => maximum_match_bytes,
    }
}

#[allow(
    clippy::too_many_lines,
    reason = "one optional transaction closes graph analysis, packed construction, and owner accounting before publication"
)]
fn try_build_k0_packed_frontier(
    limits: BuildLimits,
    incumbent_planner_work: u64,
    mandatory_cut_analysis_work: u64,
    mandatory_cut_continuation: Option<MandatoryCutContinuation<'_>>,
    maximum_match_bytes: Option<usize>,
) -> Result<K0PackedFrontierBuild, BuildError> {
    let declined = |planner_work| K0PackedFrontierBuild {
        plan: None,
        planner_work,
        storage_bytes: 0,
    };
    let Some(mandatory_cut_continuation) = mandatory_cut_continuation else {
        return Ok(declined(incumbent_planner_work));
    };
    let owner_bytes = core::mem::size_of::<K0PackedFrontierPlan>();
    if limits.packed_literal_set.max_patterns < 2
        || limits.packed_literal_set.max_pattern_bytes < 4
        || owner_bytes > limits.packed_literal_set.max_build_bytes
        || owner_bytes > limits.packed_literal_set.max_persistent_bytes
    {
        return Ok(declined(incumbent_planner_work));
    }
    let remaining_work = limits
        .max_planner_work
        .checked_sub(incumbent_planner_work)
        .ok_or(BuildError::InternalInvariant(
            "incumbent planner work exceeded its enforced limit",
        ))?;
    if remaining_work == 0 {
        return Ok(declined(incumbent_planner_work));
    }

    // The one-shot continuation retains the exact completed cut receipt and a
    // shared borrow of the RawPlan that produced it. Continuing consumes that
    // authority, so frontier enumeration cannot cross plans or observe a
    // same-address mutation. The cut work was already charged before the
    // incumbent suffix received first refusal; only new frontier work consumes
    // the remaining facade budget here.
    if mandatory_cut_analysis_work == 0
        || mandatory_cut_continuation.stats().work() != mandatory_cut_analysis_work
    {
        return Err(BuildError::InternalInvariant(
            "K0 packed-frontier continuation disagreed with its cut receipt",
        ));
    }
    let mut analysis_limits = MandatoryLiteralFrontierAnalysisLimits::default();
    analysis_limits.mandatory_cut.max_work = mandatory_cut_analysis_work;
    analysis_limits.max_work = analysis_limits.max_work.min(remaining_work);
    analysis_limits.mandatory_cut.max_allocation_items = analysis_limits
        .mandatory_cut
        .max_allocation_items
        .min(limits.lowering.max_stack_items);
    analysis_limits.max_allocation_items = analysis_limits
        .max_allocation_items
        .min(limits.lowering.max_stack_items);
    let analysis = fre_automata::continue_mandatory_literal_frontier(
        mandatory_cut_continuation,
        analysis_limits,
    );
    let stats = analysis.stats();
    if !stats.closes(analysis_limits) {
        return Err(BuildError::InternalInvariant(
            "K0 packed-frontier analysis receipt did not close",
        ));
    }
    let mut planner_work = incumbent_planner_work
        .checked_add(stats.work())
        .ok_or(BuildError::InternalInvariant(
            "cumulative K0 packed-frontier planner work overflowed",
        ))?;
    if planner_work > limits.max_planner_work {
        return Err(BuildError::InternalInvariant(
            "K0 packed-frontier analysis exceeded its admitted planner work",
        ));
    }
    let report = match analysis {
        MandatoryLiteralFrontierAnalysis::Complete(report) => report,
        MandatoryLiteralFrontierAnalysis::Declined(decline) => {
            match decline.reason() {
                MandatoryLiteralFrontierDeclineReason::Resource { .. }
                | MandatoryLiteralFrontierDeclineReason::Allocation { .. }
                | MandatoryLiteralFrontierDeclineReason::MandatoryCut(
                    MandatoryCutDeclineReason::Resource { .. }
                    | MandatoryCutDeclineReason::Allocation { .. },
                ) => return Ok(declined(planner_work)),
                MandatoryLiteralFrontierDeclineReason::MandatoryCut(
                    MandatoryCutDeclineReason::MalformedGraph(_)
                    | MandatoryCutDeclineReason::ArithmeticOverflow { .. }
                    | MandatoryCutDeclineReason::InternalInvariant { .. },
                )
                | MandatoryLiteralFrontierDeclineReason::ArithmeticOverflow { .. }
                | MandatoryLiteralFrontierDeclineReason::InternalInvariant { .. } => {
                    return Err(BuildError::InternalInvariant(
                        "lowered K0 graph failed packed-frontier analysis",
                    ));
                }
                _ => {
                    return Err(BuildError::InternalInvariant(
                        "K0 packed-frontier analysis returned an unknown decline",
                    ));
                }
            }
        }
    };
    let Some(candidate) = report.candidate() else {
        return Ok(declined(planner_work));
    };
    let Some(maximum_before_root) = k0_packed_frontier_maximum_before_root(
        candidate.maximum_before_root(),
        maximum_match_bytes,
    ) else {
        return Ok(declined(planner_work));
    };
    if candidate.len() < 2 {
        return Ok(declined(planner_work));
    }

    // The graph analyzer already publishes a deterministic prefix antichain.
    // Recheck the runtime owner's stronger multi-literal contract while the
    // candidate is still transaction-local, charging every compared member.
    let comparison_work = u64::try_from(candidate.len()).map_err(|_| {
        BuildError::InternalInvariant("K0 packed-frontier literal count does not fit work")
    })?;
    if !try_charge_k0_negative_prefilter_work(
        &mut planner_work,
        comparison_work,
        limits.max_planner_work,
    )? {
        return Ok(declined(planner_work));
    }
    let first = candidate.literal(0).ok_or(BuildError::InternalInvariant(
        "K0 packed-frontier candidate lost its first literal",
    ))?;
    if !candidate.iter().skip(1).any(|literal| literal != first) {
        return Ok(declined(planner_work));
    }

    let packed_build_work =
        packed_literal_set_build_work_upper_bound_from_dimensions(
            candidate.len(),
            stats.retained_literal_bytes(),
        )
        .map_err(|_| {
            BuildError::InternalInvariant(
                "authenticated K0 packed-frontier dimensions overflowed packed preflight",
            )
        })?;
    let packed_build_work = u64::try_from(packed_build_work).map_err(|_| {
        BuildError::InternalInvariant("K0 packed-frontier build work does not fit u64")
    })?;
    let publication_work = packed_build_work
        .checked_add(1)
        .ok_or(BuildError::InternalInvariant(
            "K0 packed-frontier publication work overflowed",
        ))?;
    if !try_charge_k0_negative_prefilter_work(
        &mut planner_work,
        publication_work,
        limits.max_planner_work,
    )? {
        return Ok(declined(planner_work));
    }

    let mut pattern_refs =
        [&[][..]; fre_automata::MAX_MANDATORY_LITERAL_FRONTIER_LITERALS];
    for (index, slot) in pattern_refs[..candidate.len()].iter_mut().enumerate() {
        *slot = candidate.literal(index).ok_or(BuildError::InternalInvariant(
            "K0 packed-frontier candidate lost a retained literal",
        ))?;
    }
    let child_limits = PackedLiteralSetBuildLimits {
        max_build_bytes: limits
            .packed_literal_set
            .max_build_bytes
            .checked_sub(owner_bytes)
            .expect("the packed-frontier owner build bytes were preflighted"),
        max_persistent_bytes: limits
            .packed_literal_set
            .max_persistent_bytes
            .checked_sub(owner_bytes)
            .expect("the packed-frontier owner persistent bytes were preflighted"),
        ..limits.packed_literal_set
    };
    let packed = match PackedLiteralSetPlan::new(
        &pattern_refs[..candidate.len()],
        child_limits,
    ) {
        Ok(packed) => packed,
        Err(
            PackedLiteralSetError::PatternLimit { .. }
            | PackedLiteralSetError::PatternBytesLimit { .. }
            | PackedLiteralSetError::BuildWorkLimit { .. }
            | PackedLiteralSetError::BuildBytesLimit { .. }
            | PackedLiteralSetError::PersistentBytesLimit { .. }
            | PackedLiteralSetError::UnsupportedTargetOrShape,
        ) => return Ok(declined(planner_work)),
        Err(_) => {
            return Err(BuildError::InternalInvariant(
                "admitted K0 packed-frontier construction failed unexpectedly",
            ));
        }
    };
    let packed_build = packed.build_accounting();
    if packed_build.patterns != candidate.len()
        || packed_build.pattern_bytes != stats.retained_literal_bytes()
        || packed_build.max_pattern_bytes != stats.maximum_literal_bytes()
    {
        return Err(BuildError::InternalInvariant(
            "K0 packed-frontier owner disagreed with its graph receipt",
        ));
    }
    let overlap_bytes = maximum_before_root
        .checked_add(packed_build.max_pattern_bytes.saturating_sub(1))
        .ok_or(BuildError::InternalInvariant(
            "K0 packed-frontier overlap overflowed",
        ))?;
    let overlap_admission = overlap_bytes
        .checked_mul(K0_PACKED_FRONTIER_OVERLAP_FACTOR)
        .ok_or(BuildError::InternalInvariant(
            "K0 packed-frontier admission overflowed",
        ))?;
    // Until this owner is bound to the exact validated automaton, preserve
    // the unscaled cheap-fallback admission. Binding may lower the overlap
    // margin from immutable transition complexity before publication.
    let minimum_window_bytes = k0_packed_frontier_minimum_window_bytes(
        packed_build.simd_minimum_haystack_bytes,
        overlap_bytes,
        overlap_admission,
        None,
    );
    let plan = K0PackedFrontierPlan {
        packed,
        automaton_identity: 0,
        maximum_before_root,
        minimum_window_bytes,
    };
    let storage_bytes = plan.storage_bytes();
    let plan = match fre_exact_alloc::try_box_preserve(plan) {
        Ok(plan) => plan,
        Err((fre_exact_alloc::CopyError::AllocationFailed, _)) => {
            return Ok(declined(planner_work));
        }
        Err((fre_exact_alloc::CopyError::LayoutOverflow, _)) => {
            return Err(BuildError::InternalInvariant(
                "K0 packed-frontier owner layout overflowed",
            ));
        }
    };
    Ok(K0PackedFrontierBuild {
        plan: Some(plan),
        planner_work,
        storage_bytes,
    })
}

#[derive(Debug)]
#[repr(transparent)]
struct K0ReverseSuffixSpanAdaptiveState {
    #[cfg(target_has_atomic = "64")]
    disabled_window_classes: core::sync::atomic::AtomicU64,
    #[cfg(not(target_has_atomic = "64"))]
    disabled_window_classes: u64,
}

struct K0ReverseSuffixSpanAdmission<'a> {
    adaptive: &'a K0ReverseSuffixSpanAdaptiveState,
    expected_transient: u64,
    success_payload: u64,
    loss_payload: u64,
    settled: bool,
}

impl K0ReverseSuffixSpanAdmission<'_> {
    fn observe_loss(mut self) {
        self.adaptive
            .settle_transient(self.expected_transient, self.loss_payload);
        self.settled = true;
    }
}

impl Drop for K0ReverseSuffixSpanAdmission<'_> {
    fn drop(&mut self) {
        if !self.settled {
            self.adaptive
                .settle_transient(self.expected_transient, self.success_payload);
        }
    }
}

impl K0ReverseSuffixSpanAdaptiveState {
    // Runtime admission already rejects windows below 2^10 bytes. Preserve
    // bits 10..=63 as the permanent size-class bitmap and use the otherwise
    // unreachable low ten bits for one bounded, source-independent retry
    // clock. One bit stripes adjacent logarithmic window classes; nine bits
    // encode six escalating skip epochs (8 through 256 calls). Class exponents
    // differing by two (window sizes differing by a factor of four) may share
    // a clock, which is harmless for this performance-only hint and preserves
    // every exact permanent class bit. The clock never stores a source
    // address, cursor, or result.
    const MIN_WINDOW_CLASS: u32 = 10;
    const TRANSIENT_EPOCH_MASK: u64 = 0x1ff;
    const TRANSIENT_COHORT_MASK: u64 = 0x200;
    const TRANSIENT_MASK: u64 = 0x3ff;
    const TRANSIENT_IN_FLIGHT: u64 = Self::TRANSIENT_EPOCH_MASK;
    const TRANSIENT_INITIAL_SKIP_CALLS: u64 = 8;
    const TRANSIENT_MAX_STAGE: u64 = 5;

    const fn new() -> Self {
        Self {
            #[cfg(target_has_atomic = "64")]
            disabled_window_classes: core::sync::atomic::AtomicU64::new(0),
            #[cfg(not(target_has_atomic = "64"))]
            disabled_window_classes: 0,
        }
    }

    fn window_class(window_bytes: usize) -> Option<u32> {
        if window_bytes == 0 {
            return None;
        }
        Some(
            (usize::BITS - 1)
            .saturating_sub(window_bytes.leading_zeros())
            .min(u64::BITS - 1),
        )
    }

    fn permanent_class_mask(window_bytes: usize) -> Option<u64> {
        Self::window_class(window_bytes)
            .filter(|class| *class >= Self::MIN_WINDOW_CLASS)
            .map(|class| 1_u64 << class)
    }

    fn transient_cohort(window_bytes: usize) -> Option<u64> {
        let class = Self::window_class(window_bytes)?;
        let stripe = class.checked_sub(Self::MIN_WINDOW_CLASS)? & 1;
        Some(u64::from(stripe) << 9)
    }

    const fn transient_stage_skip(stage: u64) -> Option<u64> {
        match stage {
            0 => Some(8),
            1 => Some(16),
            2 => Some(32),
            3 => Some(64),
            4 => Some(128),
            5 => Some(256),
            _ => None,
        }
    }

    const fn encode_transient_epoch(stage: u64, remaining: u64) -> Option<u64> {
        let (base, maximum) = match stage {
            0 => (1, 8),
            1 => (10, 16),
            2 => (27, 32),
            3 => (60, 64),
            4 => (125, 128),
            5 => (254, 256),
            _ => return None,
        };
        if remaining > maximum {
            return None;
        }
        Some(base + remaining)
    }

    const fn decode_transient_epoch(code: u64) -> Option<(u64, u64)> {
        match code {
            1..=9 => Some((0, code - 1)),
            10..=26 => Some((1, code - 10)),
            27..=59 => Some((2, code - 27)),
            60..=124 => Some((3, code - 60)),
            125..=253 => Some((4, code - 125)),
            254..=510 => Some((5, code - 254)),
            _ => None,
        }
    }

    fn initial_loss_payload(window_bytes: usize) -> Option<u64> {
        Some(
            Self::transient_cohort(window_bytes)?
                | Self::encode_transient_epoch(0, Self::TRANSIENT_INITIAL_SKIP_CALLS)
                    .expect("the initial reverse-suffix epoch is representable"),
        )
    }

    #[cfg(target_has_atomic = "64")]
    fn load(&self) -> u64 {
        self.disabled_window_classes
            .load(core::sync::atomic::Ordering::Relaxed)
    }

    #[cfg(not(target_has_atomic = "64"))]
    const fn load(&self) -> u64 {
        // Targets without one-word atomics keep the same inline shape but do
        // not adapt. Correctness never depends on this performance hint.
        let _ = self.disabled_window_classes;
        0
    }

    #[cfg(target_has_atomic = "64")]
    fn fetch_or(&self, mask: u64) -> u64 {
        self.disabled_window_classes
            .fetch_or(mask, core::sync::atomic::Ordering::Relaxed)
    }

    #[cfg(not(target_has_atomic = "64"))]
    const fn fetch_or(&self, _mask: u64) -> u64 {
        // Inert fallback: callers simply retain the deterministic capped
        // route on targets that cannot publish one relaxed machine word.
        let _ = self.disabled_window_classes;
        0
    }

    fn is_disabled(&self, window_bytes: usize) -> bool {
        Self::permanent_class_mask(window_bytes)
            .is_some_and(|mask| self.load() & mask != 0)
    }

    fn is_eligible(&self, window_bytes: usize) -> bool {
        Self::permanent_class_mask(window_bytes)
            .is_some_and(|mask| self.load() & mask == 0)
    }

    #[cfg(target_has_atomic = "64")]
    fn try_admit(&self, window_bytes: usize) -> Option<K0ReverseSuffixSpanAdmission<'_>> {
        let permanent = Self::permanent_class_mask(window_bytes)?;
        let cohort = Self::transient_cohort(window_bytes)?;
        let initial_loss_payload = Self::initial_loss_payload(window_bytes)
            .expect("an eligible reverse-suffix class has an initial epoch");
        let mut observed = self.load();
        loop {
            if observed & permanent != 0 {
                return None;
            }
            let transient = observed & Self::TRANSIENT_MASK;
            if transient & Self::TRANSIENT_EPOCH_MASK == Self::TRANSIENT_IN_FLIGHT {
                // One invocation owns the only admissible feedback token.
                // Do not let another cohort replace the claim: that would
                // permit a stale same-cohort token after the tag wraps.
                return None;
            }
            if transient == 0 || transient & Self::TRANSIENT_COHORT_MASK != cohort {
                let claim = cohort | Self::TRANSIENT_IN_FLIGHT;
                let replacement = (observed & !Self::TRANSIENT_MASK) | claim;
                match self.disabled_window_classes.compare_exchange_weak(
                    observed,
                    replacement,
                    core::sync::atomic::Ordering::Relaxed,
                    core::sync::atomic::Ordering::Relaxed,
                ) {
                    Ok(_) => {
                        return Some(K0ReverseSuffixSpanAdmission {
                            adaptive: self,
                            expected_transient: claim,
                            success_payload: transient,
                            loss_payload: initial_loss_payload,
                            settled: false,
                        });
                    }
                    Err(actual) => {
                        observed = actual;
                        continue;
                    }
                }
            }
            let code = transient & Self::TRANSIENT_EPOCH_MASK;
            let Some((stage, remaining)) = Self::decode_transient_epoch(code) else {
                // No writer publishes an empty epoch with a nonempty cohort.
                // Treat any future malformed hint like an idle clock: claim
                // it transactionally and let exact execution remeasure.
                let claim = cohort | Self::TRANSIENT_IN_FLIGHT;
                let replacement = (observed & !Self::TRANSIENT_MASK) | claim;
                match self.disabled_window_classes.compare_exchange_weak(
                    observed,
                    replacement,
                    core::sync::atomic::Ordering::Relaxed,
                    core::sync::atomic::Ordering::Relaxed,
                ) {
                    Ok(_) => {
                        return Some(K0ReverseSuffixSpanAdmission {
                            adaptive: self,
                            expected_transient: claim,
                            success_payload: 0,
                            loss_payload: initial_loss_payload,
                            settled: false,
                        });
                    }
                    Err(actual) => {
                        observed = actual;
                        continue;
                    }
                }
            };
            if remaining == 0 {
                let next_stage = stage.saturating_add(1).min(Self::TRANSIENT_MAX_STAGE);
                let next_skip = Self::transient_stage_skip(next_stage)
                    .expect("the capped reverse-suffix epoch has a skip count");
                let loss_payload = cohort
                    | Self::encode_transient_epoch(next_stage, next_skip)
                        .expect("the next reverse-suffix epoch is representable");
                let claim = cohort | Self::TRANSIENT_IN_FLIGHT;
                let replacement = (observed & !Self::TRANSIENT_MASK) | claim;
                match self.disabled_window_classes.compare_exchange_weak(
                    observed,
                    replacement,
                    core::sync::atomic::Ordering::Relaxed,
                    core::sync::atomic::Ordering::Relaxed,
                ) {
                    Ok(_) => {
                        return Some(K0ReverseSuffixSpanAdmission {
                            adaptive: self,
                            expected_transient: claim,
                            success_payload: 0,
                            loss_payload,
                            settled: false,
                        });
                    }
                    Err(actual) => {
                        observed = actual;
                        continue;
                    }
                }
            } else {
                let next_code = Self::encode_transient_epoch(stage, remaining - 1)
                    .expect("a decremented reverse-suffix epoch is representable");
                let replacement = (observed & !Self::TRANSIENT_EPOCH_MASK) | next_code;
                match self.disabled_window_classes.compare_exchange_weak(
                    observed,
                    replacement,
                    core::sync::atomic::Ordering::Relaxed,
                    core::sync::atomic::Ordering::Relaxed,
                ) {
                    Ok(_) => return None,
                    Err(actual) => observed = actual,
                }
            }
        }
    }

    #[cfg(not(target_has_atomic = "64"))]
    fn try_admit(&self, window_bytes: usize) -> Option<K0ReverseSuffixSpanAdmission<'_>> {
        // Correctness never depends on adaptive admission. Established long
        // reverse-suffix plans retain their deterministic route on targets
        // without a one-word CAS; the plan-level wrapper separately declines
        // the new short route because it can otherwise repeat a losing second
        // whole-window pass without bounded backoff.
        let _ = self.disabled_window_classes;
        Self::permanent_class_mask(window_bytes).map(|_| K0ReverseSuffixSpanAdmission {
            adaptive: self,
            expected_transient: 0,
            success_payload: 0,
            loss_payload: 0,
            settled: false,
        })
    }

    #[cfg(target_has_atomic = "64")]
    fn settle_transient(&self, expected_transient: u64, replacement_transient: u64) {
        debug_assert_eq!(expected_transient & !Self::TRANSIENT_MASK, 0);
        debug_assert_eq!(replacement_transient & !Self::TRANSIENT_MASK, 0);
        let replacement_transient = replacement_transient & Self::TRANSIENT_MASK;
        let mut observed = self.load();
        loop {
            if observed & Self::TRANSIENT_MASK != expected_transient {
                return;
            }
            let replacement = (observed & !Self::TRANSIENT_MASK) | replacement_transient;
            match self.disabled_window_classes.compare_exchange_weak(
                observed,
                replacement,
                core::sync::atomic::Ordering::Relaxed,
                core::sync::atomic::Ordering::Relaxed,
            ) {
                Ok(_) => return,
                Err(actual) => observed = actual,
            }
        }
    }

    #[cfg(not(target_has_atomic = "64"))]
    const fn settle_transient(&self, _expected_transient: u64, _replacement_transient: u64) {
        let _ = self.disabled_window_classes;
    }

    fn disable(&self, window_bytes: usize) {
        if let Some(mask) = Self::permanent_class_mask(window_bytes) {
            let _ = self.fetch_or(mask);
        }
    }
}

impl Default for K0ReverseSuffixSpanAdaptiveState {
    fn default() -> Self {
        Self::new()
    }
}

#[derive(Debug)]
struct K0ConsumptionRunPlan {
    ascii_members: AsciiByteSetRunScanner,
    high_members: [u64; 2],
    reverse_suffix_span: bool,
    // Runtime-dispatch scanners are naturally wide enough without this word;
    // use the recovered word for a source-independent performance hint while
    // preserving the incumbent aggregate layout/ABI in compiler-fixed
    // profiles too. Membership deliberately ignores it.
    reverse_suffix_span_adaptive: K0ReverseSuffixSpanAdaptiveState,
}

impl K0ConsumptionRunPlan {
    fn contains(&self, byte: u8) -> bool {
        if byte < 0x80 {
            return self.ascii_members.set().contains(byte);
        }
        let word = usize::from(byte / 64).saturating_sub(2);
        let bit = u32::from(byte % 64);
        self.high_members[word] & (1_u64 << bit) != 0
    }

    fn narrowed_start_before(&self, haystack: &[u8], window_start: usize, end: usize) -> usize {
        let mut cursor = end;
        let mut high_members = 0_usize;
        while cursor > window_start {
            let run = self
                .ascii_members
                .scan_backward(&haystack[window_start..cursor]);
            cursor = cursor.saturating_sub(run.member_run_len());
            if cursor == window_start {
                return window_start;
            }

            let byte_position = cursor.saturating_sub(1);
            let byte = haystack[byte_position];
            if !self.contains(byte) {
                // The byte at cursor - 1 cannot occur on any consuming edge,
                // so no match can cross it and the next byte is a sound lower
                // bound for every match containing the selected suffix.
                return cursor;
            }

            // Every admitted ASCII member is consumed by the run scanner. A
            // remaining exact member is therefore high. Bound scalar recovery
            // independently of the source; exhausting the bound fails open
            // all the way to the original window start.
            debug_assert!(byte > 0x7f);
            if high_members >= K0_SUFFIX_HIGH_BYTE_BACKWARD_MAX {
                return window_start;
            }
            high_members = high_members.saturating_add(1);
            cursor = byte_position;
        }
        window_start
    }
}

#[derive(Debug)]
enum K0MandatorySuffixRecoveryPlan {
    None,
    ConsumptionRun(K0ConsumptionRunPlan),
    UniversalFiniteCorridor {
        minimum_match_bytes: usize,
        maximum_match_bytes: usize,
        prefix_hedge_bytes: usize,
    },
    UniversalFiniteGreedyCorridor {
        minimum_match_bytes: usize,
        maximum_match_bytes: usize,
        prefix_hedge_bytes: usize,
    },
    FiniteMaximum {
        minimum_match_bytes: usize,
        maximum_match_bytes: usize,
        prefix_hedge_bytes: usize,
    },
    FiniteMaximumSpanOnly {
        minimum_match_bytes: usize,
        maximum_match_bytes: usize,
        prefix_hedge_bytes: usize,
    },
    // Append the source-order variant so all incumbent implicit discriminants
    // remain stable. Its adaptive word fits the incumbent enum envelope; a
    // consumption-run plan carries the same word in capacity recovered by
    // removing redundant ASCII bitmap words.
    ReverseSuffixSpan(K0ReverseSuffixSpanAdaptiveState),
}

#[derive(Debug)]
struct K0MandatorySuffixPlan {
    literal: LiteralPlan,
    recovery: K0MandatorySuffixRecoveryPlan,
}

impl K0MandatorySuffixPlan {
    fn needle(&self) -> &[u8] {
        self.literal.needle()
    }

    fn find_window(
        &self,
        haystack: &[u8],
        start: usize,
        end: usize,
    ) -> Result<Option<(usize, usize)>, LiteralError> {
        self.literal
            .find_window(
                haystack,
                LiteralWindow::new(start, end),
                LiteralSearchLimits::unlimited(),
            )
            .map(|(matched, _)| matched)
    }

    fn rfind_window(
        &self,
        haystack: &[u8],
        start: usize,
        end: usize,
    ) -> Result<Option<(usize, usize)>, LiteralError> {
        self.literal
            .rfind_window(
                haystack,
                LiteralWindow::new(start, end),
                LiteralSearchLimits::unlimited(),
            )
            .map(|(matched, _)| matched)
    }

    fn narrowed_start_before(&self, haystack: &[u8], window_start: usize, end: usize) -> usize {
        let scanner = match &self.recovery {
            K0MandatorySuffixRecoveryPlan::ConsumptionRun(scanner) => scanner,
            _ => return window_start,
        };
        scanner.narrowed_start_before(haystack, window_start, end)
    }

    fn has_consumption_run(&self) -> bool {
        matches!(
            &self.recovery,
            K0MandatorySuffixRecoveryPlan::ConsumptionRun(_)
        )
    }

    fn has_reverse_suffix_span(&self) -> bool {
        self.reverse_suffix_span_adaptive().is_some()
    }

    fn has_short_standalone_reverse_suffix_span(&self) -> bool {
        self.needle().len() < K0_MANDATORY_SUFFIX_MIN_NEEDLE_BYTES
            && matches!(
                &self.recovery,
                K0MandatorySuffixRecoveryPlan::ReverseSuffixSpan(_)
            )
    }

    fn reverse_suffix_span_adaptive(&self) -> Option<&K0ReverseSuffixSpanAdaptiveState> {
        match &self.recovery {
            K0MandatorySuffixRecoveryPlan::ConsumptionRun(scanner)
                if scanner.reverse_suffix_span => Some(&scanner.reverse_suffix_span_adaptive),
            K0MandatorySuffixRecoveryPlan::ReverseSuffixSpan(adaptive) => Some(adaptive),
            _ => None,
        }
    }

    fn reverse_suffix_span_is_disabled(&self, window_bytes: usize) -> bool {
        self.reverse_suffix_span_adaptive()
            .is_some_and(|adaptive| adaptive.is_disabled(window_bytes))
    }

    #[inline]
    fn reverse_suffix_span_is_eligible(&self, window_bytes: usize) -> bool {
        self.reverse_suffix_span_adaptive()
            .is_some_and(|adaptive| adaptive.is_eligible(window_bytes))
    }

    #[inline]
    fn try_admit_reverse_suffix_span(
        &self,
        window_bytes: usize,
    ) -> Option<K0ReverseSuffixSpanAdmission<'_>> {
        #[cfg(not(target_has_atomic = "64"))]
        if self.has_short_standalone_reverse_suffix_span() {
            return None;
        }
        self.reverse_suffix_span_adaptive()
            .and_then(|adaptive| adaptive.try_admit(window_bytes))
    }

    fn disable_reverse_suffix_span(&self, window_bytes: usize) {
        if let Some(adaptive) = self.reverse_suffix_span_adaptive() {
            adaptive.disable(window_bytes);
        }
    }

    fn finite_maximum_match_bytes(&self) -> Option<usize> {
        self.finite_match_byte_bounds()
            .map(|(_, maximum)| maximum)
    }

    fn finite_minimum_match_bytes(&self) -> Option<usize> {
        self.finite_match_byte_bounds()
            .map(|(minimum, _)| minimum)
    }

    fn finite_match_byte_bounds(&self) -> Option<(usize, usize)> {
        match &self.recovery {
            K0MandatorySuffixRecoveryPlan::UniversalFiniteCorridor {
                minimum_match_bytes,
                maximum_match_bytes,
                ..
            }
            | K0MandatorySuffixRecoveryPlan::UniversalFiniteGreedyCorridor {
                minimum_match_bytes,
                maximum_match_bytes,
                ..
            }
            | K0MandatorySuffixRecoveryPlan::FiniteMaximum {
                minimum_match_bytes,
                maximum_match_bytes,
                ..
            }
            | K0MandatorySuffixRecoveryPlan::FiniteMaximumSpanOnly {
                minimum_match_bytes,
                maximum_match_bytes,
                ..
            } => Some((*minimum_match_bytes, *maximum_match_bytes)),
            K0MandatorySuffixRecoveryPlan::None
            | K0MandatorySuffixRecoveryPlan::ConsumptionRun(_)
            | K0MandatorySuffixRecoveryPlan::ReverseSuffixSpan(_) => None,
        }
    }

    fn finite_exists_maximum_match_bytes(&self) -> Option<usize> {
        match &self.recovery {
            K0MandatorySuffixRecoveryPlan::UniversalFiniteCorridor {
                maximum_match_bytes,
                ..
            }
            | K0MandatorySuffixRecoveryPlan::UniversalFiniteGreedyCorridor {
                maximum_match_bytes,
                ..
            }
            | K0MandatorySuffixRecoveryPlan::FiniteMaximum {
                maximum_match_bytes,
                ..
            } => Some(*maximum_match_bytes),
            K0MandatorySuffixRecoveryPlan::None
            | K0MandatorySuffixRecoveryPlan::ConsumptionRun(_)
            | K0MandatorySuffixRecoveryPlan::ReverseSuffixSpan(_)
            | K0MandatorySuffixRecoveryPlan::FiniteMaximumSpanOnly { .. } => None,
        }
    }

    fn universal_finite_match_byte_bounds(&self) -> Option<(usize, usize)> {
        match &self.recovery {
            K0MandatorySuffixRecoveryPlan::UniversalFiniteCorridor {
                minimum_match_bytes,
                maximum_match_bytes,
                ..
            }
            | K0MandatorySuffixRecoveryPlan::UniversalFiniteGreedyCorridor {
                minimum_match_bytes,
                maximum_match_bytes,
                ..
            } => Some((*minimum_match_bytes, *maximum_match_bytes)),
            K0MandatorySuffixRecoveryPlan::None
            | K0MandatorySuffixRecoveryPlan::ConsumptionRun(_)
            | K0MandatorySuffixRecoveryPlan::ReverseSuffixSpan(_)
            | K0MandatorySuffixRecoveryPlan::FiniteMaximum { .. }
            | K0MandatorySuffixRecoveryPlan::FiniteMaximumSpanOnly { .. } => None,
        }
    }

    fn has_universal_finite_greedy_corridor(&self) -> bool {
        matches!(
            &self.recovery,
            K0MandatorySuffixRecoveryPlan::UniversalFiniteGreedyCorridor { .. }
        )
    }

    fn finite_span_only_maximum_match_bytes(&self) -> Option<usize> {
        match &self.recovery {
            K0MandatorySuffixRecoveryPlan::FiniteMaximumSpanOnly {
                maximum_match_bytes,
                ..
            } => Some(*maximum_match_bytes),
            K0MandatorySuffixRecoveryPlan::None
            | K0MandatorySuffixRecoveryPlan::ConsumptionRun(_)
            | K0MandatorySuffixRecoveryPlan::ReverseSuffixSpan(_)
            | K0MandatorySuffixRecoveryPlan::UniversalFiniteCorridor { .. }
            | K0MandatorySuffixRecoveryPlan::UniversalFiniteGreedyCorridor { .. }
            | K0MandatorySuffixRecoveryPlan::FiniteMaximum { .. } => None,
        }
    }

    fn finite_prefix_hedge_bytes(&self) -> Option<usize> {
        match &self.recovery {
            K0MandatorySuffixRecoveryPlan::UniversalFiniteCorridor {
                prefix_hedge_bytes,
                ..
            }
            | K0MandatorySuffixRecoveryPlan::UniversalFiniteGreedyCorridor {
                prefix_hedge_bytes,
                ..
            }
            | K0MandatorySuffixRecoveryPlan::FiniteMaximum { prefix_hedge_bytes, .. }
            | K0MandatorySuffixRecoveryPlan::FiniteMaximumSpanOnly {
                prefix_hedge_bytes,
                ..
            } => Some(*prefix_hedge_bytes),
            K0MandatorySuffixRecoveryPlan::None
            | K0MandatorySuffixRecoveryPlan::ConsumptionRun(_)
            | K0MandatorySuffixRecoveryPlan::ReverseSuffixSpan(_) => None,
        }
    }
}

struct K0MandatorySuffixBuild {
    plan: Option<K0MandatorySuffixPlan>,
    planner_work: u64,
    storage_bytes: usize,
    deferred_short_unbounded: Option<MandatorySuffixCandidate>,
}

fn k0_finite_suffix_prefix_hedge_bytes(
    maximum_match_bytes: usize,
    suffix_bytes: usize,
    mandatory_cut: Option<K0MandatoryCutPlan>,
) -> usize {
    let maximum_prefix = maximum_match_bytes.saturating_sub(suffix_bytes);
    let cut_maximum_before = mandatory_cut
        .map(|cut| match cut.maximum_before_root() {
            MaximumConsumedDistance::Finite(maximum) => {
                usize::try_from(maximum).unwrap_or(usize::MAX)
            }
            MaximumConsumedDistance::Unbounded => maximum_prefix,
        })
        .unwrap_or(maximum_prefix)
        .min(maximum_prefix);
    // One complete directional proof envelope covers the finite prefix, one
    // full ordered replay, the cut-to-root displacement, and one classified
    // seek block. The break-even extension uses only immutable plan geometry:
    // expected incumbent candidate work scales with cut cardinality and full
    // width, while suffix verification scales with the maximum pre-suffix
    // prefix. A narrow modeled advantage gives the incumbent a longer hedge;
    // a decisive suffix advantage keeps almost only the proof envelope.
    let proof_envelope = maximum_prefix
        .saturating_add(maximum_match_bytes)
        .saturating_add(cut_maximum_before)
        .saturating_add(BYTE_SET_BLOCK_BYTES);
    let incumbent_cost = mandatory_cut
        .map_or(1, K0MandatoryCutPlan::cardinality)
        .saturating_mul(maximum_match_bytes.max(1));
    let suffix_cost = maximum_prefix.max(1);
    let advantage = incumbent_cost.saturating_sub(suffix_cost).max(1);
    let proof = u128::try_from(proof_envelope).unwrap_or(u128::MAX);
    let extension = proof
        .saturating_mul(u128::try_from(suffix_cost).unwrap_or(u128::MAX))
        .div_ceil(u128::try_from(advantage).unwrap_or(u128::MAX));
    let extension = usize::try_from(extension)
        .unwrap_or(usize::MAX)
        .min(K0_SUFFIX_FORWARD_FALLBACK_BYTES);
    proof_envelope.saturating_add(extension)
}

#[cfg(test)]
fn try_build_k0_mandatory_suffix(
    raw: &fre_automata::RawPlan,
    structural_hir: Option<&Hir>,
    minimum_match_bytes: Option<usize>,
    maximum_match_bytes: Option<usize>,
    mandatory_cut: Option<K0MandatoryCutPlan>,
    limits: BuildLimits,
    incumbent_planner_work: u64,
) -> Result<K0MandatorySuffixBuild, BuildError> {
    try_build_k0_mandatory_suffix_with_short_policy(
        raw,
        structural_hir,
        minimum_match_bytes,
        maximum_match_bytes,
        mandatory_cut,
        limits,
        incumbent_planner_work,
        true,
    )
}

#[allow(
    clippy::too_many_arguments,
    reason = "the deferred short owner reuses the authenticated suffix transaction"
)]
fn try_build_k0_mandatory_suffix_with_short_policy(
    raw: &fre_automata::RawPlan,
    structural_hir: Option<&Hir>,
    minimum_match_bytes: Option<usize>,
    maximum_match_bytes: Option<usize>,
    mandatory_cut: Option<K0MandatoryCutPlan>,
    limits: BuildLimits,
    incumbent_planner_work: u64,
    admit_short_unbounded: bool,
) -> Result<K0MandatorySuffixBuild, BuildError> {
    let declined = |planner_work| K0MandatorySuffixBuild {
        plan: None,
        planner_work,
        storage_bytes: 0,
        deferred_short_unbounded: None,
    };
    let remaining_work = limits
        .max_planner_work
        .checked_sub(incumbent_planner_work)
        .ok_or(BuildError::InternalInvariant(
            "incumbent planner work exceeded its enforced limit",
        ))?;
    if remaining_work == 0 {
        return Ok(declined(incumbent_planner_work));
    }
    let mut analysis_limits = MandatorySuffixAnalysisLimits::default();
    analysis_limits.max_work = analysis_limits.max_work.min(remaining_work);
    analysis_limits.max_allocation_items = analysis_limits
        .max_allocation_items
        .min(limits.lowering.max_stack_items);
    let analysis = fre_automata::analyze_mandatory_suffix(raw, analysis_limits);
    let stats = analysis.stats();
    let assertion_edges = stats.assertion_edges();
    if !stats.closes(analysis_limits) {
        return Err(BuildError::InternalInvariant(
            "K0 mandatory-suffix analysis receipt did not close",
        ));
    }
    let mut planner_work = incumbent_planner_work
        .checked_add(stats.work())
        .ok_or(BuildError::InternalInvariant(
            "cumulative K0 mandatory-suffix planner work overflowed u64",
        ))?;
    if planner_work > limits.max_planner_work {
        return Err(BuildError::InternalInvariant(
            "K0 mandatory-suffix analysis exceeded its admitted planner work",
        ));
    }
    let candidate = match analysis {
        MandatorySuffixAnalysis::Complete(report) => report.candidate(),
        MandatorySuffixAnalysis::Declined(decline) => match decline.reason() {
            MandatorySuffixDeclineReason::Resource {
                resource:
                    MandatorySuffixResource::SuffixBytes
                    | MandatorySuffixResource::Work
                    | MandatorySuffixResource::AllocationItems
                    | MandatorySuffixResource::AllocationAttempts,
                ..
            }
            | MandatorySuffixDeclineReason::Allocation { .. }
            | MandatorySuffixDeclineReason::AssertionsPresent
            | MandatorySuffixDeclineReason::EmptyLanguage
            | MandatorySuffixDeclineReason::NullableLanguage
            | MandatorySuffixDeclineReason::AmbiguousSuffixLayer => {
                return Ok(declined(planner_work));
            }
            MandatorySuffixDeclineReason::MalformedGraph(_)
            | MandatorySuffixDeclineReason::ArithmeticOverflow { .. }
            | MandatorySuffixDeclineReason::InternalInvariant { .. } => {
                return Err(BuildError::InternalInvariant(
                    "lowered K0 graph failed mandatory-suffix analysis",
                ));
            }
            _ => {
                return Err(BuildError::InternalInvariant(
                    "K0 mandatory-suffix analysis returned an unknown decline",
                ));
            }
        },
    };
    let finite_bounds = match maximum_match_bytes {
        Some(maximum) => match minimum_match_bytes {
            Some(minimum) if minimum > 0 && minimum <= maximum => {
                Some((minimum, maximum))
            }
            Some(_) | None => {
                return Err(BuildError::InternalInvariant(
                    "finite mandatory suffix has inconsistent HIR width bounds",
                ));
            }
        },
        None => None,
    };
    let finite_positive = finite_bounds.is_some();
    let short_unbounded =
        candidate.len() < K0_MANDATORY_SUFFIX_MIN_NEEDLE_BYTES && !finite_positive;
    if short_unbounded {
        if !admit_short_unbounded {
            return Ok(K0MandatorySuffixBuild {
                plan: None,
                planner_work,
                storage_bytes: 0,
                deferred_short_unbounded: Some(candidate),
            });
        }
        return try_build_k0_deferred_short_mandatory_suffix(
            candidate,
            structural_hir,
            limits,
            planner_work,
        );
    }
    if maximum_match_bytes.is_some_and(|maximum| candidate.len() > maximum) {
        return Err(BuildError::InternalInvariant(
            "mandatory suffix exceeds the HIR maximum match width",
        ));
    }
    if finite_bounds.is_some_and(|(minimum, _)| candidate.len() > minimum) {
        return Err(BuildError::InternalInvariant(
            "mandatory suffix exceeds the HIR minimum match width",
        ));
    }
    // Short finite suffixes have no incumbent suffix sidecar, so finite
    // recovery remains their first choice. Longer suffixes first retain the
    // existing consumption-run recovery exactly; if that proof declines, the
    // already-authenticated finite width bounds are still sufficient to bound
    // exact reverse start recovery and reject subminimum occurrences instead
    // of leaving the retained suffix unused by Span operations.
    let short_finite_recovery_bounds = if candidate.len()
        < K0_MANDATORY_SUFFIX_MIN_NEEDLE_BYTES
    {
        finite_bounds
    } else {
        None
    };
    let copy_work = u64::try_from(candidate.len()).map_err(|_| {
        BuildError::InternalInvariant("K0 mandatory suffix length does not fit u64")
    })?;
    if !try_charge_k0_negative_prefilter_work(
        &mut planner_work,
        copy_work,
        limits.max_planner_work,
    )? {
        return Ok(declined(planner_work));
    }
    let literal = match LiteralPlan::new(candidate.as_bytes(), limits.literal) {
        Ok(literal) => literal,
        Err(LiteralError::NeedleLimit { .. } | LiteralError::AllocationFailed { .. }) => {
            return Ok(declined(planner_work));
        }
        Err(_) => {
            return Err(BuildError::InternalInvariant(
                "admitted K0 mandatory suffix failed literal construction",
            ));
        }
    };
    if !try_charge_k0_negative_prefilter_work(&mut planner_work, 1, limits.max_planner_work)? {
        return Ok(declined(planner_work));
    }
    let finite_recovery = |(minimum_match_bytes, maximum_match_bytes)| {
        K0MandatorySuffixRecoveryPlan::FiniteMaximum {
            minimum_match_bytes,
            maximum_match_bytes,
            prefix_hedge_bytes: k0_finite_suffix_prefix_hedge_bytes(
                maximum_match_bytes,
                candidate.len(),
                mandatory_cut,
            ),
        }
    };
    let finite_span_recovery = |(minimum_match_bytes, maximum_match_bytes)| {
        K0MandatorySuffixRecoveryPlan::FiniteMaximumSpanOnly {
            minimum_match_bytes,
            maximum_match_bytes,
            prefix_hedge_bytes: k0_finite_suffix_prefix_hedge_bytes(
                maximum_match_bytes,
                candidate.len(),
                mandatory_cut,
            ),
        }
    };
    let universal_finite_recovery = |(minimum_match_bytes, maximum_match_bytes)| {
        K0MandatorySuffixRecoveryPlan::UniversalFiniteCorridor {
            minimum_match_bytes,
            maximum_match_bytes,
            prefix_hedge_bytes: k0_finite_suffix_prefix_hedge_bytes(
                maximum_match_bytes,
                candidate.len(),
                mandatory_cut,
            ),
        }
    };
    let universal_finite_greedy_recovery = |(minimum_match_bytes, maximum_match_bytes)| {
        K0MandatorySuffixRecoveryPlan::UniversalFiniteGreedyCorridor {
            minimum_match_bytes,
            maximum_match_bytes,
            prefix_hedge_bytes: k0_finite_suffix_prefix_hedge_bytes(
                maximum_match_bytes,
                candidate.len(),
                mandatory_cut,
            ),
        }
    };
    let baseline_recovery = if let Some(bounds) = short_finite_recovery_bounds {
        finite_recovery(bounds)
    } else {
        match try_build_k0_consumption_run(raw, &mut planner_work, limits.max_planner_work)? {
            Some(run) => K0MandatorySuffixRecoveryPlan::ConsumptionRun(run),
            // A semantic decline (the union is empty or covers every byte)
            // and a planner-resource refusal are both safe here. The HIR's
            // finite width bounds were authenticated before this optional
            // scan and the Span-only recovery needs no additional planner
            // work. In particular, rebuilding at the refused attempt's
            // reported work limit deterministically makes the same choice.
            None => finite_bounds
                .map_or(K0MandatorySuffixRecoveryPlan::None, finite_span_recovery),
        }
    };
    // The graph analysis above proves only that `candidate` is mandatory. For
    // an unbounded match, visiting suffix occurrences in source order also
    // needs a separate HIR theorem before the first reverse-confirmed
    // occurrence can be published as the globally leftmost start. Keep this
    // optional, allocation-free inspection after the incumbent recovery is
    // complete: resource or semantic refusal preserves the old suffix plan
    // byte-for-byte, while success upgrades only its zero-layout tag.
    let mut recovery = baseline_recovery;
    if maximum_match_bytes.is_none()
        && let Some(hir) = structural_hir
        && planner_work < limits.max_planner_work
    {
        let structural_limit = planner_work
            .saturating_add(K0_REVERSE_SUFFIX_SPAN_MAX_WORK)
            .min(limits.max_planner_work);
        match k0_reverse_suffix_span::inspect(
            hir,
            candidate.as_bytes(),
            planner_work,
            structural_limit,
        ) {
            Ok(outcome) => {
                let inspected_work = outcome.planner_work();
                if inspected_work < planner_work || inspected_work > structural_limit {
                    return Err(BuildError::InternalInvariant(
                        "reverse-suffix Span proof work receipt did not close",
                    ));
                }
                planner_work = inspected_work;
                if let k0_reverse_suffix_span::InspectionOutcome::Eligible(inspection) = outcome {
                    if inspection.planner_work() != inspected_work {
                        return Err(BuildError::InternalInvariant(
                            "reverse-suffix Span eligible receipt did not close",
                        ));
                    }
                    let _proof = inspection.proof();
                    recovery = match recovery {
                        K0MandatorySuffixRecoveryPlan::ConsumptionRun(mut scanner) => {
                            scanner.reverse_suffix_span = true;
                            K0MandatorySuffixRecoveryPlan::ConsumptionRun(scanner)
                        }
                        K0MandatorySuffixRecoveryPlan::None => {
                            K0MandatorySuffixRecoveryPlan::ReverseSuffixSpan(
                                K0ReverseSuffixSpanAdaptiveState::new(),
                            )
                        }
                        _ => {
                            return Err(BuildError::InternalInvariant(
                                "unbounded reverse-suffix proof found a finite recovery",
                            ));
                        }
                    };
                }
            }
            Err(k0_reverse_suffix_span::InspectionError::WorkLimit {
                actual,
                ..
            }) => {
                if actual < planner_work || actual > structural_limit {
                    return Err(BuildError::InternalInvariant(
                        "reverse-suffix Span proof refusal receipt did not close",
                    ));
                }
                planner_work = actual;
            }
            Err(k0_reverse_suffix_span::InspectionError::ArithmeticOverflow) => {
                return Err(BuildError::InternalInvariant(
                    "reverse-suffix Span proof accounting overflowed",
                ));
            }
        }
    }
    // The generic suffix, literal, and ordinary recovery are now complete.
    // Spend only the remaining optional planner budget on an independently
    // versioned corridor proof. Any refusal retains `baseline_recovery`
    // exactly; only a closed success replaces its zero-layout recovery tag.
    if let Some((minimum, maximum)) = finite_bounds {
        let baseline_can_be_upgraded = matches!(
            &recovery,
            K0MandatorySuffixRecoveryPlan::FiniteMaximum { .. }
                | K0MandatorySuffixRecoveryPlan::FiniteMaximumSpanOnly { .. }
        );
        let mut greedy_corridor_completed = false;
        if baseline_can_be_upgraded && assertion_edges == 0 {
            if let Some(hir) = structural_hir {
                if planner_work < limits.max_planner_work {
                    let structural_limit = planner_work
                        .saturating_add(K0_UNIVERSAL_FINITE_GREEDY_CORRIDOR_MAX_WORK)
                        .min(limits.max_planner_work);
                    match universal_finite_greedy_corridor::inspect(
                        hir,
                        candidate.as_bytes(),
                        planner_work,
                        structural_limit,
                    ) {
                        Ok(outcome) => {
                            let inspected_work = outcome.planner_work();
                            if inspected_work < planner_work
                                || inspected_work > structural_limit
                            {
                                return Err(BuildError::InternalInvariant(
                                    "greedy universal-corridor work receipt did not close",
                                ));
                            }
                            planner_work = inspected_work;
                            if let universal_finite_greedy_corridor::InspectionOutcome::Eligible(
                                inspection,
                            ) = outcome
                            {
                                if inspection.planner_work() != planner_work {
                                    return Err(BuildError::InternalInvariant(
                                        "greedy universal-corridor eligible receipt diverged",
                                    ));
                                }
                                let descriptor = inspection.descriptor();
                                let expected_minimum_prefix = minimum
                                    .checked_sub(candidate.len())
                                    .ok_or(BuildError::InternalInvariant(
                                        "greedy universal-corridor minimum prefix underflowed",
                                    ))?;
                                let expected_maximum_prefix = maximum
                                    .checked_sub(candidate.len())
                                    .ok_or(BuildError::InternalInvariant(
                                        "greedy universal-corridor maximum prefix underflowed",
                                    ))?;
                                if descriptor.suffix_bytes() != candidate.len()
                                    || descriptor.minimum_match_bytes() != minimum
                                    || descriptor.maximum_match_bytes() != maximum
                                    || descriptor.minimum_prefix_bytes()
                                        != expected_minimum_prefix
                                    || descriptor.maximum_prefix_bytes()
                                        != expected_maximum_prefix
                                {
                                    return Err(BuildError::InternalInvariant(
                                        "greedy universal corridor disagrees with authenticated K0 geometry",
                                    ));
                                }
                                recovery =
                                    universal_finite_greedy_recovery((minimum, maximum));
                                greedy_corridor_completed = true;
                            }
                        }
                        Err(universal_finite_greedy_corridor::InspectionError::WorkLimit {
                            actual,
                            ..
                        }) => {
                            if actual < planner_work || actual > structural_limit {
                                return Err(BuildError::InternalInvariant(
                                    "greedy universal-corridor refusal receipt did not close",
                                ));
                            }
                            planner_work = actual;
                        }
                        Err(
                            universal_finite_greedy_corridor::InspectionError::ArithmeticOverflow,
                        ) => {
                            return Err(BuildError::InternalInvariant(
                                "greedy universal-corridor inspection overflowed",
                            ));
                        }
                    }
                }
            }
        }
        let remaining_corridor_work = limits.max_planner_work.saturating_sub(planner_work);
        if baseline_can_be_upgraded
            && !greedy_corridor_completed
            && remaining_corridor_work != 0
        {
            let mut corridor_limits = MandatorySuffixAnalysisLimits::default();
            corridor_limits.max_work = corridor_limits.max_work.min(remaining_corridor_work);
            corridor_limits.max_allocation_items = corridor_limits
                .max_allocation_items
                .min(limits.lowering.max_stack_items);
            let corridor_analysis =
                fre_automata::analyze_mandatory_suffix_universal_finite_corridor(
                    raw,
                    corridor_limits,
                    minimum,
                    maximum,
                );
            let corridor_stats = corridor_analysis.stats();
            if !corridor_stats.closes(corridor_limits) {
                return Err(BuildError::InternalInvariant(
                    "K0 universal mandatory-suffix corridor receipt did not close",
                ));
            }
            planner_work = planner_work.checked_add(corridor_stats.work()).ok_or(
                BuildError::InternalInvariant(
                    "cumulative universal mandatory-suffix planner work overflowed u64",
                ),
            )?;
            if planner_work > limits.max_planner_work {
                return Err(BuildError::InternalInvariant(
                    "universal mandatory-suffix analysis exceeded its admitted planner work",
                ));
            }
            match corridor_analysis {
                fre_automata::MandatorySuffixUniversalFiniteCorridorAnalysis::Complete(
                    report,
                ) => {
                    if report.candidate().as_bytes() != candidate.as_bytes() {
                        return Err(BuildError::InternalInvariant(
                            "universal corridor re-authenticated a different mandatory suffix",
                        ));
                    }
                    let corridor = report.corridor();
                    let expected_minimum_prefix = minimum.checked_sub(candidate.len()).ok_or(
                        BuildError::InternalInvariant(
                            "universal mandatory-suffix minimum prefix underflowed",
                        ),
                    )?;
                    let expected_maximum_prefix = maximum.checked_sub(candidate.len()).ok_or(
                        BuildError::InternalInvariant(
                            "universal mandatory-suffix maximum prefix underflowed",
                        ),
                    )?;
                    if corridor.minimum_prefix_bytes() != expected_minimum_prefix
                        || corridor.maximum_prefix_bytes() != expected_maximum_prefix
                    {
                        return Err(BuildError::InternalInvariant(
                            "universal mandatory-suffix corridor disagrees with HIR widths",
                        ));
                    }
                    recovery = universal_finite_recovery((minimum, maximum));
                }
                fre_automata::MandatorySuffixUniversalFiniteCorridorAnalysis::Declined(
                    decline,
                ) => match decline.reason() {
                    fre_automata::MandatorySuffixUniversalFiniteCorridorDeclineReason::NotUniversal
                    | fre_automata::MandatorySuffixUniversalFiniteCorridorDeclineReason::PrefixDepthLimit { .. }
                    | fre_automata::MandatorySuffixUniversalFiniteCorridorDeclineReason::Analysis(
                        MandatorySuffixDeclineReason::Resource { .. }
                        | MandatorySuffixDeclineReason::Allocation { .. }
                        | MandatorySuffixDeclineReason::AssertionsPresent
                        | MandatorySuffixDeclineReason::EmptyLanguage
                        | MandatorySuffixDeclineReason::NullableLanguage
                        | MandatorySuffixDeclineReason::AmbiguousSuffixLayer,
                    ) => {}
                    fre_automata::MandatorySuffixUniversalFiniteCorridorDeclineReason::Analysis(
                        MandatorySuffixDeclineReason::MalformedGraph(_)
                        | MandatorySuffixDeclineReason::ArithmeticOverflow { .. }
                        | MandatorySuffixDeclineReason::InternalInvariant { .. },
                    )
                    | fre_automata::MandatorySuffixUniversalFiniteCorridorDeclineReason::InternalReceiptInvariant => {
                        return Err(BuildError::InternalInvariant(
                            "lowered K0 graph failed universal mandatory-suffix analysis",
                        ));
                    }
                    _ => {
                        return Err(BuildError::InternalInvariant(
                            "universal mandatory-suffix analysis returned an unknown decline",
                        ));
                    }
                },
            }
        }
    }
    let storage_bytes = core::mem::size_of::<K0MandatorySuffixPlan>()
        .checked_add(literal.storage_bytes())
        .ok_or(BuildError::PersistentBytesOverflow)?;
    Ok(K0MandatorySuffixBuild {
        plan: Some(K0MandatorySuffixPlan {
            literal,
            recovery,
        }),
        planner_work,
        storage_bytes,
        deferred_short_unbounded: None,
    })
}

fn try_build_k0_deferred_short_mandatory_suffix(
    candidate: MandatorySuffixCandidate,
    structural_hir: Option<&Hir>,
    limits: BuildLimits,
    mut planner_work: u64,
) -> Result<K0MandatorySuffixBuild, BuildError> {
    let declined = |planner_work| K0MandatorySuffixBuild {
        plan: None,
        planner_work,
        storage_bytes: 0,
        deferred_short_unbounded: None,
    };
    let Some(hir) = structural_hir else {
        return Ok(declined(planner_work));
    };
    if candidate.is_empty()
        || candidate.len() >= K0_MANDATORY_SUFFIX_MIN_NEEDLE_BYTES
        || planner_work >= limits.max_planner_work
    {
        return Ok(declined(planner_work));
    }
    // Short unbounded suffixes previously had no owner. Admit one only when a
    // bounded allocation-free source theorem proves suffix order and the
    // singleton survives Rust's poison rule. Actual retained FRE owners have
    // already consumed their planner/storage authority before production
    // calls this transaction.
    let structural_limit = planner_work
        .saturating_add(K0_REVERSE_SUFFIX_SPAN_MAX_WORK)
        .min(limits.max_planner_work);
    match k0_reverse_suffix_span::inspect(
        hir,
        candidate.as_bytes(),
        planner_work,
        structural_limit,
    ) {
        Ok(k0_reverse_suffix_span::InspectionOutcome::Eligible(inspection)) => {
            let inspected_work = inspection.planner_work();
            if inspected_work < planner_work || inspected_work > structural_limit {
                return Err(BuildError::InternalInvariant(
                    "short reverse-suffix Span proof work receipt did not close",
                ));
            }
            planner_work = inspected_work;
        }
        Ok(k0_reverse_suffix_span::InspectionOutcome::Ineligible {
            planner_work: inspected_work,
        }) => {
            if inspected_work < planner_work || inspected_work > structural_limit {
                return Err(BuildError::InternalInvariant(
                    "short reverse-suffix Span refusal work receipt did not close",
                ));
            }
            return Ok(declined(inspected_work));
        }
        Err(k0_reverse_suffix_span::InspectionError::WorkLimit { actual, .. }) => {
            if actual < planner_work || actual > structural_limit {
                return Err(BuildError::InternalInvariant(
                    "short reverse-suffix Span work refusal did not close",
                ));
            }
            return Ok(declined(actual));
        }
        Err(k0_reverse_suffix_span::InspectionError::ArithmeticOverflow) => {
            return Err(BuildError::InternalInvariant(
                "short reverse-suffix Span proof accounting overflowed",
            ));
        }
    }
    let copy_work = u64::try_from(candidate.len()).map_err(|_| {
        BuildError::InternalInvariant("short mandatory suffix length does not fit u64")
    })?;
    if !try_charge_k0_negative_prefilter_work(
        &mut planner_work,
        copy_work,
        limits.max_planner_work,
    )? {
        return Ok(declined(planner_work));
    }
    let literal = match LiteralPlan::new(candidate.as_bytes(), limits.literal) {
        Ok(literal) => literal,
        Err(LiteralError::NeedleLimit { .. } | LiteralError::AllocationFailed { .. }) => {
            return Ok(declined(planner_work));
        }
        Err(_) => {
            return Err(BuildError::InternalInvariant(
                "admitted short mandatory suffix failed literal construction",
            ));
        }
    };
    if !try_charge_k0_negative_prefilter_work(&mut planner_work, 1, limits.max_planner_work)? {
        return Ok(declined(planner_work));
    }
    let storage_bytes = core::mem::size_of::<K0MandatorySuffixPlan>()
        .checked_add(literal.storage_bytes())
        .ok_or(BuildError::PersistentBytesOverflow)?;
    Ok(K0MandatorySuffixBuild {
        plan: Some(K0MandatorySuffixPlan {
            literal,
            recovery: K0MandatorySuffixRecoveryPlan::ReverseSuffixSpan(
                K0ReverseSuffixSpanAdaptiveState::new(),
            ),
        }),
        planner_work,
        storage_bytes,
        deferred_short_unbounded: None,
    })
}

fn try_build_k0_consumption_run(
    raw: &fre_automata::RawPlan,
    planner_work: &mut u64,
    max_planner_work: u64,
) -> Result<Option<K0ConsumptionRunPlan>, BuildError> {
    let edge_work = u64::try_from(raw.edge_kinds.len()).map_err(|_| {
        BuildError::InternalInvariant("K0 consuming-edge count does not fit planner work")
    })?;
    if !try_charge_k0_negative_prefilter_work(planner_work, edge_work, max_planner_work)? {
        return Ok(None);
    }

    let mut members = [0_u64; 4];
    for (edge, &kind) in raw.edge_kinds.iter().enumerate() {
        if kind != fre_automata::EdgeKind::ByteRange {
            continue;
        }
        let start = raw.byte_starts[edge];
        let end = raw.byte_ends[edge];
        insert_k0_consumption_range(&mut members, start, end)?;
    }
    if members == [0; 4] || members == [u64::MAX; 4] {
        return Ok(None);
    }
    if !try_charge_k0_negative_prefilter_work(
        planner_work,
        u64::try_from(ASCII_RUN_SCANNER_BUILD_WORK)
            .expect("ASCII run-scanner construction work fits u64"),
        max_planner_work,
    )? {
        return Ok(None);
    }
    Ok(Some(K0ConsumptionRunPlan {
        ascii_members: AsciiByteSetRunScanner::new(AsciiByteSet::from_words([
            members[0],
            members[1],
        ])),
        high_members: [members[2], members[3]],
        reverse_suffix_span: false,
        reverse_suffix_span_adaptive: K0ReverseSuffixSpanAdaptiveState::new(),
    }))
}

fn insert_k0_consumption_range(
    members: &mut [u64; 4],
    start: u8,
    end: u8,
) -> Result<(), BuildError> {
    if start > end {
        return Err(BuildError::InternalInvariant(
            "lowered K0 consuming range is reversed",
        ));
    }
    let first_word = usize::from(start / 64);
    let last_word = usize::from(end / 64);
    for word_index in first_word..=last_word {
        let first_bit = if word_index == first_word {
            u32::from(start % 64)
        } else {
            0
        };
        let last_bit = if word_index == last_word {
            u32::from(end % 64)
        } else {
            u64::BITS - 1
        };
        let through_last = if last_bit == u64::BITS - 1 {
            u64::MAX
        } else {
            1_u64
                .checked_shl(last_bit.saturating_add(1))
                .and_then(|mask| mask.checked_sub(1))
                .ok_or(BuildError::InternalInvariant(
                    "lowered K0 consuming range upper mask overflowed",
                ))?
        };
        let below_first = if first_bit == 0 {
            0
        } else {
            1_u64
                .checked_shl(first_bit)
                .and_then(|mask| mask.checked_sub(1))
                .ok_or(BuildError::InternalInvariant(
                    "lowered K0 consuming range lower mask overflowed",
                ))?
        };
        members[word_index] |= through_last & !below_first;
    }
    Ok(())
}

#[derive(Debug)]
struct K0NegativePrefilterPlan {
    literals: fre_exact_alloc::ExactVec<LiteralPlan>,
    maximum_needle_bytes: usize,
}

impl K0NegativePrefilterPlan {
    fn primary_needle_bytes(&self) -> Option<usize> {
        self.literals
            .iter()
            .map(|literal| literal.needle().len())
            .max()
    }
}

struct K0NegativePrefilterBuild {
    plan: Option<Box<K0NegativePrefilterPlan>>,
    planner_work: u64,
    storage_bytes: usize,
}

fn try_charge_k0_negative_prefilter_work(
    work: &mut u64,
    amount: u64,
    limit: u64,
) -> Result<bool, BuildError> {
    let needed = work.checked_add(amount).ok_or(BuildError::InternalInvariant(
        "K0 negative-prefilter planner work overflowed",
    ))?;
    if needed > limit {
        return Ok(false);
    }
    *work = needed;
    Ok(true)
}

fn try_build_k0_negative_prefilter(
    hir: &Hir,
    minimum_match_bytes: Option<usize>,
    limits: BuildLimits,
    incumbent_planner_work: u64,
    source_storage_bytes: usize,
    capture_name_storage_bytes: usize,
    automaton_storage_bytes: usize,
) -> Result<K0NegativePrefilterBuild, BuildError> {
    let declined = |planner_work| K0NegativePrefilterBuild {
        plan: None,
        planner_work,
        storage_bytes: 0,
    };
    if !matches!(minimum_match_bytes, Some(minimum) if minimum > 0) {
        return Ok(declined(incumbent_planner_work));
    }
    // K0 can reject a fully absolute-start-anchored pattern without injecting
    // candidate starts across the window. A whole-window literal pass would
    // turn that constant-prefix rejection into a linear scan.
    if hir.properties().look_set_prefix().contains(Look::Start) {
        return Ok(declined(incumbent_planner_work));
    }
    let base_persistent_bytes = source_storage_bytes
        .checked_add(capture_name_storage_bytes)
        .and_then(|bytes| bytes.checked_add(automaton_storage_bytes))
        .ok_or(BuildError::PersistentBytesOverflow)?;
    let minimum_sidecar_bytes = core::mem::size_of::<K0NegativePrefilterPlan>()
        .checked_add(core::mem::size_of::<LiteralPlan>())
        .and_then(|bytes| bytes.checked_add(K0_NEGATIVE_PREFILTER_MIN_NEEDLE_BYTES))
        .ok_or(BuildError::PersistentBytesOverflow)?;
    if limits
        .max_persistent_bytes
        .saturating_sub(base_persistent_bytes)
        < minimum_sidecar_bytes
    {
        return Ok(declined(incumbent_planner_work));
    }

    let remaining_planner_work = limits
        .max_planner_work
        .checked_sub(incumbent_planner_work)
        .ok_or(BuildError::InternalInvariant(
            "incumbent planner work exceeded its enforced limit",
        ))?;
    if remaining_planner_work == 0 {
        return Ok(declined(incumbent_planner_work));
    }
    let mut inspection_limits = CaptureRequiredLiteralBuildLimits::default();
    inspection_limits.max_planner_work = inspection_limits.max_planner_work.min(
        usize::try_from(remaining_planner_work).unwrap_or(usize::MAX),
    );
    inspection_limits.max_needle_bytes = inspection_limits
        .max_needle_bytes
        .min(K0_NEGATIVE_PREFILTER_MAX_NEEDLE_BYTES);

    let inspection =
        match capture_required_literal::inspect_conjunctive_required_literals(hir, inspection_limits)
        {
            Ok(inspection) => inspection,
            Err(failure) => {
                let actual_work = u64::try_from(failure.actual_work).map_err(|_| {
                    BuildError::InternalInvariant(
                        "K0 negative-prefilter planner work does not fit u64",
                    )
                })?;
                let planner_work = incumbent_planner_work.checked_add(actual_work).ok_or(
                    BuildError::InternalInvariant(
                        "cumulative K0 negative-prefilter planner work overflowed u64",
                    ),
                )?;
                if planner_work > limits.max_planner_work {
                    return Err(BuildError::InternalInvariant(
                        "K0 negative-prefilter attempt exceeded its planner-work admission",
                    ));
                }
                return match failure.source {
                    CaptureRequiredLiteralBuildError::Resource { .. }
                    | CaptureRequiredLiteralBuildError::Allocation { .. } => {
                        Ok(declined(planner_work))
                    }
                    CaptureRequiredLiteralBuildError::Overflow(computation)
                    | CaptureRequiredLiteralBuildError::InternalInvariant(computation) => {
                        Err(BuildError::InternalInvariant(computation))
                    }
                    CaptureRequiredLiteralBuildError::LiteralSet(_) => {
                        Err(BuildError::InternalInvariant(
                            "proof-only K0 negative-prefilter inspection constructed a literal set",
                        ))
                    }
                };
            }
        };
    let actual_work = u64::try_from(inspection.actual_work).map_err(|_| {
        BuildError::InternalInvariant("K0 negative-prefilter planner work does not fit u64")
    })?;
    let mut planner_work = incumbent_planner_work.checked_add(actual_work).ok_or(
        BuildError::InternalInvariant(
            "cumulative K0 negative-prefilter planner work overflowed u64",
        ),
    )?;
    if planner_work > limits.max_planner_work {
        return Err(BuildError::InternalInvariant(
            "K0 negative-prefilter inspection exceeded its planner-work admission",
        ));
    }
    let inspected = inspection
        .literals
        .get(..inspection.count)
        .ok_or(BuildError::InternalInvariant(
            "K0 negative-prefilter inspection count exceeded inline literals",
        ))?;
    let inspected_work = u64::try_from(inspected.len()).map_err(|_| {
        BuildError::InternalInvariant("K0 negative-prefilter inspected count does not fit u64")
    })?;
    if !try_charge_k0_negative_prefilter_work(
        &mut planner_work,
        inspected_work,
        limits.max_planner_work,
    )? {
        return Ok(declined(planner_work));
    }
    let mut eligible = [None; capture_required_literal::MAX_CONJUNCTIVE_REQUIRED_LITERALS];
    let mut literal_count = 0usize;
    let mut literal_bytes = 0usize;
    let mut maximum_needle_bytes = 0usize;
    for &literal in inspected {
        if literal.len() > K0_NEGATIVE_PREFILTER_MAX_NEEDLE_BYTES
            || literal.len() > limits.literal.max_needle_bytes
        {
            continue;
        }
        *eligible
            .get_mut(literal_count)
            .ok_or(BuildError::InternalInvariant(
                "K0 negative-prefilter eligible literals exceeded inline storage",
            ))? = Some(literal);
        literal_count = literal_count
            .checked_add(1)
            .ok_or(BuildError::PersistentBytesOverflow)?;
        literal_bytes = literal_bytes
            .checked_add(literal.len())
            .ok_or(BuildError::PersistentBytesOverflow)?;
        maximum_needle_bytes = maximum_needle_bytes.max(literal.len());
    }
    // Every retained literal is independently mandatory. Short predicates are
    // absence-only filters in the runtime below: a present byte never proposes
    // an endpoint and adaptive backoff returns repeatedly positive inputs to
    // K0. Keeping them in this last-priority sidecar avoids displacing the
    // graph cut or the more capable exact-suffix verifier.
    if literal_count == 0 {
        return Ok(declined(planner_work));
    }
    let storage_bytes = core::mem::size_of::<K0NegativePrefilterPlan>()
        .checked_add(
            literal_count
                .checked_mul(core::mem::size_of::<LiteralPlan>())
                .ok_or(BuildError::PersistentBytesOverflow)?,
        )
        .and_then(|bytes| bytes.checked_add(literal_bytes))
        .ok_or(BuildError::PersistentBytesOverflow)?;
    let charged_with_sidecar = base_persistent_bytes
        .checked_add(storage_bytes)
        .ok_or(BuildError::PersistentBytesOverflow)?;
    if charged_with_sidecar > limits.max_persistent_bytes {
        return Ok(declined(planner_work));
    }
    if !try_charge_k0_negative_prefilter_work(
        &mut planner_work,
        1,
        limits.max_planner_work,
    )? {
        return Ok(declined(planner_work));
    }
    let mut literals = match fre_exact_alloc::ExactVec::try_with_capacity(literal_count) {
        Ok(literals) => literals,
        Err(fre_exact_alloc::CopyError::AllocationFailed) => {
            return Ok(declined(planner_work));
        }
        Err(fre_exact_alloc::CopyError::LayoutOverflow) => {
            return Err(BuildError::InternalInvariant(
                "K0 negative-prefilter literal vector layout overflowed",
            ));
        }
    };
    for literal in eligible[..literal_count].iter().copied() {
        let literal = literal.ok_or(BuildError::InternalInvariant(
            "K0 negative-prefilter eligible literal was not initialized",
        ))?;
        let copy_work = u64::try_from(literal.len()).map_err(|_| {
            BuildError::InternalInvariant("K0 negative-prefilter literal size does not fit u64")
        })?;
        if !try_charge_k0_negative_prefilter_work(
            &mut planner_work,
            copy_work,
            limits.max_planner_work,
        )? {
            return Ok(declined(planner_work));
        }
        let plan = match LiteralPlan::new(literal, limits.literal) {
            Ok(plan) => plan,
            Err(LiteralError::NeedleLimit { .. } | LiteralError::AllocationFailed { .. }) => {
                return Ok(declined(planner_work));
            }
            Err(_) => {
                return Err(BuildError::InternalInvariant(
                    "admitted K0 negative-prefilter literal failed infallible construction",
                ));
            }
        };
        if !try_charge_k0_negative_prefilter_work(
            &mut planner_work,
            1,
            limits.max_planner_work,
        )? {
            return Ok(declined(planner_work));
        }
        literals.try_push(plan).map_err(|_| {
            BuildError::InternalInvariant(
                "admitted K0 negative-prefilter vector rejected a literal",
            )
        })?;
    }
    let plan = K0NegativePrefilterPlan {
        literals,
        maximum_needle_bytes,
    };
    if !try_charge_k0_negative_prefilter_work(
        &mut planner_work,
        1,
        limits.max_planner_work,
    )? {
        return Ok(declined(planner_work));
    }
    let plan = match fre_exact_alloc::try_box_preserve(plan) {
        Ok(plan) => plan,
        Err((fre_exact_alloc::CopyError::AllocationFailed, _)) => {
            return Ok(declined(planner_work));
        }
        Err((fre_exact_alloc::CopyError::LayoutOverflow, _)) => {
            return Err(BuildError::InternalInvariant(
                "K0 negative-prefilter owner layout overflowed",
            ));
        }
    };
    Ok(K0NegativePrefilterBuild {
        plan: Some(plan),
        planner_work,
        storage_bytes,
    })
}

fn folded_tail_planner_work_upper_bound(
    hir_nodes: u64,
    literal_set: &LiteralSetPlan,
) -> Option<u64> {
    let finite = literal_set.build_accounting();
    let pattern_bytes = u64::try_from(finite.pattern_bytes).ok()?;
    let patterns = u64::try_from(finite.patterns).ok()?;
    // Exhaustive finite extraction preserves every expansion and duplicate.
    // Its aggregate bytes bound both folded scalar positions and equivalent
    // scalar memberships, while its word count bounds source alternatives.
    // Folded inspection plus materialization costs at most 2H + S + 2E + 2P.
    hir_nodes
        .checked_mul(2)?
        .checked_add(pattern_bytes.checked_mul(3)?)?
        .checked_add(patterns.checked_mul(2)?)
}

struct FixedPredicateAutoAttempt {
    plan: Option<Box<FixedPredicateWord64Plan>>,
    planner_work: u64,
    plan_storage_bytes: usize,
    charged_persistent_bytes: usize,
    declined: bool,
}

#[allow(clippy::too_many_arguments, clippy::too_many_lines)]
fn try_fixed_predicate_word64_before_finite(
    hir: &Hir,
    expected_hir_nodes: u64,
    explicit_captures: usize,
    initial_work: u64,
    planner_work_limit: u64,
    finite_max_patterns: usize,
    finite_max_pattern_bytes: usize,
    source_storage_bytes: usize,
    capture_name_storage_bytes: usize,
    persistent_byte_limit: usize,
) -> Result<FixedPredicateAutoAttempt, BuildError> {
    let inspection = finite::inspect_fixed_predicate_word64_attempt(
        hir,
        initial_work,
        planner_work_limit,
    );
    if !inspection.has_closed_receipt() {
        return Err(BuildError::InternalInvariant(
            "fixed-predicate search inspection lost its attempt closure",
        ));
    }
    let receipt = inspection.receipt();
    if receipt.initial_work() != initial_work || receipt.work_limit() != planner_work_limit {
        return Err(BuildError::InternalInvariant(
            "fixed-predicate search inspection lost its cumulative planner envelope",
        ));
    }
    let planner_work = receipt.actual().work;
    let fixed = match inspection {
        finite::FixedPredicateInspectionAttempt::Succeeded { source, .. } => source,
        finite::FixedPredicateInspectionAttempt::Refused { .. } => {
            return Ok(FixedPredicateAutoAttempt {
                plan: None,
                planner_work,
                plan_storage_bytes: 0,
                charged_persistent_bytes: 0,
                declined: false,
            });
        }
        finite::FixedPredicateInspectionAttempt::ResourceFailure { error, .. } => {
            return Err(error);
        }
    };
    let expected_hir_nodes = usize::try_from(expected_hir_nodes)
        .map_err(|_| BuildError::InternalInvariant("syntax HIR-node count does not fit usize"))?;
    if fixed.hir_nodes() != expected_hir_nodes || fixed.captures() != explicit_captures {
        return Err(BuildError::InternalInvariant(
            "syntax summary differs from fixed-predicate search inspection",
        ));
    }
    if fixed.variable_predicates() == 0 {
        return Err(BuildError::InternalInvariant(
            "fixed-predicate search source lost its variable predicate proof",
        ));
    }
    let mut normalized =
        [finite::FixedPredicateRanges::EMPTY; FIXED_PREDICATE_WORD64_MAX_WIDTH];
    for (index, ranges) in fixed.positions().enumerate() {
        let Some(slot) = normalized.get_mut(index) else {
            return Err(BuildError::InternalInvariant(
                "fixed-predicate search source exceeded its inline width",
            ));
        };
        *slot = ranges;
    }
    let Some(normalized) = normalized.get(..fixed.width()) else {
        return Err(BuildError::InternalInvariant(
            "fixed-predicate search source width exceeded its inline storage",
        ));
    };
    let mut positions: [&[(u8, u8)]; FIXED_PREDICATE_WORD64_MAX_WIDTH] =
        [&[]; FIXED_PREDICATE_WORD64_MAX_WIDTH];
    for (slot, predicate) in positions.iter_mut().zip(normalized) {
        *slot = predicate.ranges();
    }
    let attempt = match FixedPredicateWord64Plan::build_attempt(
        &positions[..normalized.len()],
        FixedPredicateWord64BuildLimits::unlimited(),
    ) {
        Ok(attempt) => attempt,
        Err(error) => {
            if !error.closes() {
                return Err(BuildError::InternalInvariant(
                    "fixed-predicate search construction failure lost its attempt closure",
                ));
            }
            return Err(BuildError::InternalInvariant(
                "inspected fixed-predicate search source failed kernel construction",
            ));
        }
    };
    if !attempt.closes() {
        return Err(BuildError::InternalInvariant(
            "fixed-predicate search construction lost its attempt closure",
        ));
    }
    let (plan, _) = attempt.into_parts();
    let general_primary_scan = plan.general_primary_scan_identity();
    let strategy =
        plan.search_operation_identity(FixedPredicateWord64SearchOperation::Exists);
    let reducer = strategy.reducer;
    let exact_anchor = matches!(
        reducer,
        FixedPredicateWord64Reducer::OneByteAnchor | FixedPredicateWord64Reducer::TwoByteAnchor
    );
    let staged_general = match general_primary_scan {
        Some(FixedPredicateWord64GeneralPrimaryScanIdentity::Memchr3) => true,
        Some(FixedPredicateWord64GeneralPrimaryScanIdentity::CompiledWholeSlice) => true,
        Some(FixedPredicateWord64GeneralPrimaryScanIdentity::DirectCandidateStream) | None => false,
    };
    let fixed_shift_and = matches!(reducer, FixedPredicateWord64Reducer::ShiftAnd)
        && strategy.primary_finder.is_some()
        && staged_general
        && fixed.has_non_universal_predicate()
        && fixed.finite_incumbent_cannot_fit(finite_max_patterns, finite_max_pattern_bytes);
    let auto_admitted = (exact_anchor || fixed_shift_and)
        && plan.max_verification_predicates()
            <= FIXED_PREDICATE_SEARCH_AUTO_MAX_VERIFICATION_PREDICATES;
    if !auto_admitted {
        return Ok(FixedPredicateAutoAttempt {
            plan: None,
            planner_work,
            plan_storage_bytes: 0,
            charged_persistent_bytes: 0,
            declined: true,
        });
    }
    let plan_storage_bytes = plan.build_accounting().persistent_bytes;
    let charged_persistent_bytes = source_storage_bytes
        .checked_add(capture_name_storage_bytes)
        .and_then(|bytes| bytes.checked_add(plan_storage_bytes))
        .ok_or(BuildError::PersistentBytesOverflow)?;
    if charged_persistent_bytes > persistent_byte_limit {
        return Err(BuildError::PersistentBytesLimit {
            needed: charged_persistent_bytes,
            limit: persistent_byte_limit,
        });
    }
    let plan = fre_exact_alloc::try_box_preserve(plan).map_err(|(error, _)| match error {
        fre_exact_alloc::CopyError::LayoutOverflow => {
            BuildError::InternalInvariant("fixed-predicate search owner layout overflowed")
        }
        fre_exact_alloc::CopyError::AllocationFailed => BuildError::AllocationFailed {
            structure: "fixed-predicate search owner",
            additional: 1,
        },
    })?;
    Ok(FixedPredicateAutoAttempt {
        plan: Some(plan),
        planner_work,
        plan_storage_bytes,
        charged_persistent_bytes,
        declined: false,
    })
}

#[cold]
#[inline(never)]
fn try_attach_unicode_folded_long_tail(
    attachment: LiteralSetFoldAttachment<'_>,
    parsed_hir: (&Hir, u64),
    profile: &RustProfile,
    limits: &BuildLimits,
    retained_facade_bytes: usize,
    incumbent_planner_work: u64,
) -> Result<(LiteralSetPlan, u64), BuildError> {
    let (hir, hir_nodes) = parsed_hir;
    let available_plan_bytes = limits
        .max_persistent_bytes
        .saturating_sub(retained_facade_bytes);
    let dfa_bytes = attachment.plan().build_accounting().persistent_bytes;
    let Some(available_trie_bytes) =
        available_plan_bytes
            .checked_sub(dfa_bytes)
            .and_then(|bytes| {
                bytes.checked_sub(LiteralSetPlan::folded_long_tail_additional_owner_bytes())
            })
    else {
        return Ok((attachment.into_plan(), incumbent_planner_work));
    };
    let remaining_planner_work = limits
        .max_planner_work
        .checked_sub(incumbent_planner_work)
        .ok_or(BuildError::InternalInvariant(
            "incumbent planner work exceeded its enforced limit",
        ))?;
    let Some(folded_planner_work_upper_bound) =
        folded_tail_planner_work_upper_bound(hir_nodes, attachment.plan())
    else {
        return Ok((attachment.into_plan(), incumbent_planner_work));
    };
    if folded_planner_work_upper_bound > remaining_planner_work {
        return Ok((attachment.into_plan(), incumbent_planner_work));
    }
    let planner_limit = usize::try_from(remaining_planner_work).unwrap_or(usize::MAX);
    let mut folded_limits = UnicodeFoldedLiteralBuildLimits::default();
    folded_limits.max_planner_work = folded_limits.max_planner_work.min(planner_limit);
    folded_limits.trie.max_work = folded_limits.trie.max_work.min(planner_limit);
    folded_limits.trie.max_persistent_bytes = folded_limits
        .trie
        .max_persistent_bytes
        .min(available_trie_bytes);
    folded_limits.trie.max_peak_bytes = folded_limits.trie.max_peak_bytes.min(available_trie_bytes);

    let attempt = unicode_folded_literal::build_search_plan(
        SimdDispatchContext::capture(),
        hir,
        profile,
        folded_limits,
    );
    let (plan, folded_planner) = match attempt {
        Ok(UnicodeFoldedLiteralBuildAttempt::Admitted(plan)) => {
            let work = plan.build_accounting().planner.work;
            (Some(plan), work)
        }
        Ok(UnicodeFoldedLiteralBuildAttempt::Ineligible { planner, .. }) => (None, planner.work),
        Err(attempt_error) => {
            let (error, completed_planner) = attempt_error.into_parts();
            if !unicode_folded_literal_resource_refusal(&error) {
                return Err(map_unicode_folded_literal_build_error(error));
            }
            (None, completed_planner)
        }
    };
    let planner_work = charge_unicode_folded_planner_work(
        incumbent_planner_work,
        folded_planner,
        limits.max_planner_work,
    )?;
    let literal_set = if let Some(plan) = plan {
        attachment
            .try_attach(plan.into_trie(), available_plan_bytes)?
            .0
    } else {
        attachment.into_plan()
    };
    Ok((literal_set, planner_work))
}

impl fmt::Display for BuildError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Syntax(error) => write!(f, "syntax construction failed: {error}"),
            Self::Lower(error) => write!(f, "portable lowering failed: {error}"),
            Self::Literal(error) => write!(f, "literal-plan construction failed: {error}"),
            Self::LiteralSet(error) => {
                write!(f, "literal-set DFA construction failed: {error}")
            }
            Self::RequiredLiteral(error) => {
                write!(f, "required-literal construction failed: {error}")
            }
            Self::LiteralClassRunLiteral(error) => {
                write!(f, "literal/class-run construction failed: {error}")
            }
            Self::ReverseInner(error) => {
                write!(f, "reverse-inner construction failed: {error}")
            }
            Self::PrefixClassAlternation(error) => {
                write!(f, "prefix/class alternation construction failed: {error}")
            }
            Self::RequiredLiteralShape => {
                f.write_str("pattern is outside the forced required-literal HIR shape")
            }
            Self::ForwardAnchored(error) => {
                write!(f, "forward-anchored construction failed: {error}")
            }
            Self::ForwardAnchoredShape => {
                f.write_str("pattern is outside the forced forward-anchored HIR shape")
            }
            Self::PlannerWorkLimit { needed, limit } => {
                write!(f, "planner needs {needed} work units, exceeding {limit}")
            }
            Self::PersistentBytesOverflow => {
                f.write_str("portable matcher persistent-byte accounting overflowed usize")
            }
            Self::PersistentBytesLimit { needed, limit } => write!(
                f,
                "portable matcher needs {needed} persistent bytes, exceeding {limit}"
            ),
            Self::AllocationFailed {
                structure,
                additional,
            } => write!(
                f,
                "failed to reserve {additional} additional items for planner {structure}"
            ),
            Self::InternalInvariant(detail) => {
                write!(f, "facade internal invariant failed: {detail}")
            }
        }
    }
}

impl std::error::Error for BuildError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Syntax(error) => Some(error),
            Self::Lower(error) => Some(error),
            Self::Literal(error) => Some(error),
            Self::LiteralSet(error) => Some(error),
            Self::RequiredLiteral(error) => Some(error),
            Self::LiteralClassRunLiteral(error) => Some(error),
            Self::ReverseInner(error) => Some(error),
            Self::PrefixClassAlternation(error) => Some(error),
            Self::ForwardAnchored(error) => Some(error),
            Self::RequiredLiteralShape
            | Self::ForwardAnchoredShape
            | Self::PlannerWorkLimit { .. }
            | Self::PersistentBytesOverflow
            | Self::PersistentBytesLimit { .. }
            | Self::AllocationFailed { .. }
            | Self::InternalInvariant(_) => None,
        }
    }
}

impl BuildReport {
    fn enforce_persistent_limit(mut self, limit: usize) -> Result<Self, BuildError> {
        let needed = self
            .source_storage_bytes
            .checked_add(self.capture_name_storage_bytes)
            .and_then(|bytes| bytes.checked_add(self.plan_storage_bytes))
            .ok_or(BuildError::PersistentBytesOverflow)?;
        if needed > limit {
            return Err(BuildError::PersistentBytesLimit { needed, limit });
        }
        self.charged_persistent_bytes = needed;
        self.persistent_byte_limit = limit;
        Ok(self)
    }
}

impl From<fre_syntax::ParseError> for BuildError {
    fn from(value: fre_syntax::ParseError) -> Self {
        Self::Syntax(value)
    }
}

impl From<fre_lower::LowerError> for BuildError {
    fn from(value: fre_lower::LowerError) -> Self {
        Self::Lower(value)
    }
}

impl From<LiteralError> for BuildError {
    fn from(value: LiteralError) -> Self {
        Self::Literal(value)
    }
}

impl From<LiteralSetError> for BuildError {
    fn from(value: LiteralSetError) -> Self {
        Self::LiteralSet(value)
    }
}

impl From<RequiredLiteralBuildError> for BuildError {
    fn from(value: RequiredLiteralBuildError) -> Self {
        Self::RequiredLiteral(value)
    }
}

