    #[test]
    fn short_reverse_suffix_value_route_respects_its_authority_gates() {
        const PATTERN: &str = r"(?-u:(?:abx|a|aby|a|abz|foo)q+)";

        fn adaptive(session: &PortableSearchSession<'_>) -> u64 {
            match &session.plan {
                PortableSearchSessionPlan::K0 {
                    mandatory_suffix: Some(suffix),
                    ..
                } => suffix.reverse_suffix_span_adaptive().unwrap().load(),
                _ => panic!("short reverse-suffix fixture lost its K0 owner"),
            }
        }

        let regex = forced_k0_with_reverse_suffix_span(PATTERN);
        let mut haystack = vec![b'!'; 4_096];
        haystack[8..14].copy_from_slice(b"abzqqq");
        let expected = Some(Match { start: 8, end: 14 });

        let mut endpoint = regex
            .endpoint_search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert!(!match &endpoint.plan {
            PortableSearchSessionPlan::K0 { session, .. } => {
                session.positive_end_verifier_available()
            }
            _ => unreachable!(),
        });
        assert_eq!(
            endpoint
                .find_value(&haystack, SearchLimits::unlimited())
                .unwrap(),
            expected,
        );
        assert_eq!(adaptive(&endpoint), 0);

        let mut finite = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let finite_limits = SearchLimits {
            max_work: u64::MAX - 1,
            max_scratch_bytes: usize::MAX,
        };
        assert_eq!(finite.find_value(&haystack, finite_limits).unwrap(), expected);
        assert_eq!(adaptive(&finite), 0);

        let mut short = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert_eq!(
            short
                .find_window_value(
                    &haystack,
                    SearchWindow::new(0, 1_023),
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            expected,
        );
        assert_eq!(adaptive(&short), 0);

        let mut diagnostic = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert_eq!(
            diagnostic
                .find_window(
                    &haystack,
                    SearchWindow::full(&haystack),
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .0,
            expected,
        );
        assert_eq!(adaptive(&diagnostic), 0);
        assert!(diagnostic
            .find_window_value(
                &haystack,
                SearchWindow::new(20, 10),
                SearchLimits::unlimited(),
            )
            .is_err());
        assert_eq!(adaptive(&diagnostic), 0);

        let absolute =
            forced_k0_with_reverse_suffix_span(r"(?-u:(?:abx|a|aby|a|abz|foo)q+\z)");
        let mut absolute_session = absolute
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        assert_eq!(
            absolute_session
                .find_value(&haystack, SearchLimits::unlimited())
                .unwrap(),
            None,
        );
        assert_eq!(adaptive(&absolute_session), 0);
    }

    #[test]
    fn pooled_cut_absence_leaves_reverse_suffix_adaptation_untouched() {
        const PATTERN: &str = r"(?-u:[AB]{2}Q(?:[0-9]+[ab]+)+XYZ)";
        let regex = forced_k0_with_reverse_suffix_span_and_cut(PATTERN);
        let PortablePlan::K0(plan) = &regex.plan else {
            unreachable!("focused helper installs K0");
        };
        let cut = *plan.mandatory_cut.as_ref().unwrap();
        assert_eq!(cut.maximum_before_root(), MaximumConsumedDistance::Finite(2));
        let suffix = plan.mandatory_suffix.as_ref().unwrap();
        assert_eq!(suffix.reverse_suffix_span_adaptive().unwrap().load(), 0);

        // Dense suffix decoys make an independent suffix pass nontrivial. The
        // cut byte Q is absent, so cut-first execution completes the negative
        // result and leaves the route's plan-only adaptive state untouched.
        let mut haystack = vec![b'!'; 4_096];
        for ordinal in 0..=super::K0_SUFFIX_MAX_CANDIDATES {
            let start = 1_200 + ordinal * 64;
            haystack[start..start + 3].copy_from_slice(b"XYZ");
        }
        assert_eq!(
            regex.find_value(&haystack, SearchLimits::unlimited()).unwrap(),
            None,
        );
        let PortablePlan::K0(plan) = &regex.plan else {
            unreachable!("focused helper installs K0");
        };
        assert_eq!(
            plan.mandatory_suffix
                .as_ref()
                .unwrap()
                .reverse_suffix_span_adaptive()
                .unwrap()
                .load(),
            0,
        );
    }

    #[test]
    fn pooled_cut_floor_skips_impossible_suffixes_and_bounds_the_reverse_window() {
        const PATTERN: &str = r"(?-u:[AB]{2}Q(?:[0-9]+[ab]+)+XYZ)";
        let regex = forced_k0_with_reverse_suffix_span_and_cut(PATTERN);
        let PortablePlan::K0(plan) = &regex.plan else {
            unreachable!("focused helper installs K0");
        };
        let cut = *plan.mandatory_cut.as_ref().unwrap();
        assert_eq!(cut.maximum_before_root(), MaximumConsumedDistance::Finite(2));

        let mut haystack = vec![b'!'; 8_192];
        for ordinal in 0..=super::K0_SUFFIX_MAX_CANDIDATES {
            let start = 1_200 + ordinal * 64;
            haystack[start..start + 3].copy_from_slice(b"XYZ");
        }
        haystack[6_000..6_008].copy_from_slice(b"ABQ0aXYZ");
        let expected = Some(Match {
            start: 6_000,
            end: 6_008,
        });
        assert_eq!(
            cut.first_member(&haystack).and_then(|member| cut.candidate_floor(0, member)),
            Some(6_000),
        );
        assert_eq!(
            regex.find_value(&haystack, SearchLimits::unlimited()).unwrap(),
            expected,
        );
        let PortablePlan::K0(plan) = &regex.plan else {
            unreachable!("focused helper installs K0");
        };
        let suffix = plan.mandatory_suffix.as_ref().unwrap();
        // The decoys occur before the first mandatory Q and cannot be terminal
        // suffixes of a match. The cut proof skips them and supplies the exact
        // lower bound for the residual reverse window. Starting at that bound
        // is still inclusive and therefore recovers the match.
        assert!(!suffix.reverse_suffix_span_is_disabled(haystack.len()));
        if cfg!(target_has_atomic = "64") {
            let adaptive = suffix.reverse_suffix_span_adaptive().unwrap();
            assert_eq!(
                super::K0ReverseSuffixSpanAdaptiveState::decode_transient_epoch(
                    adaptive.load()
                        & super::K0ReverseSuffixSpanAdaptiveState::TRANSIENT_EPOCH_MASK,
                ),
                Some((0, 8)),
                "a completed zero-prefix route publishes transient cost feedback",
            );
        }
    }

    #[test]
    fn reverse_suffix_span_floor_crossing_bypasses_without_source_state() {
        // This finite fixture is test-only tagged to exercise the runtime
        // theorem directly: the prefix contains an internal `XYZ` candidate,
        // while its real terminal suffix is later. The second reverse search
        // would need to cross the prior endpoint, so the bounded sidecar must
        // bypass. Ordinary K0 remains authoritative and finds the straddling
        // match; the source-dependent bypass must not disable this plan class.
        let mut regex = forced_k0_with_bound_hir_mandatory_suffix(r"(?-u:[A-Z]{10}XYZ)");
        let PortablePlan::K0(plan) = &mut regex.plan else {
            unreachable!("fixture installs K0");
        };
        let suffix = plan.mandatory_suffix.as_mut().unwrap();
        suffix.recovery = K0MandatorySuffixRecoveryPlan::ReverseSuffixSpan(
            super::K0ReverseSuffixSpanAdaptiveState::new(),
        );
        let mut haystack = vec![b'!'; 4_096];
        haystack[2_000..2_013].copy_from_slice(b"ABCXYZDEFGXYZ");
        let expected = Some(Match {
            start: 2_000,
            end: 2_013,
        });
        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let PortableSearchSessionPlan::K0 {
            session: k0_session,
            mandatory_suffix: Some(suffix),
            ..
        } = &mut session.plan
        else {
            panic!("runtime fixture retains K0 suffix");
        };
        assert_eq!(
            try_execute_k0_reverse_suffix_span(
                k0_session,
                suffix,
                &haystack,
                SearchWindow::full(&haystack),
                SearchLimits::unlimited(),
            )
            .unwrap(),
            K0ReverseSuffixSpanAttempt::Bypass,
        );
        assert!(!suffix.reverse_suffix_span_is_disabled(haystack.len()));
        assert_eq!(
            session
                .find_value(&haystack, SearchLimits::unlimited())
                .unwrap(),
            expected,
        );

        // Reusing the same allocation cannot retain the prior result or any
        // source cursor. A second immutable matcher remains plan-local too.
        let address = haystack.as_ptr();
        haystack[2_000..2_013].fill(b'!');
        assert_eq!(haystack.as_ptr(), address);
        assert_eq!(
            session
                .find_value(&haystack, SearchLimits::unlimited())
                .unwrap(),
            None,
        );
        let other = forced_k0_with_reverse_suffix_span(r"(?-u:(?:[0-9]+[ab]+)+QRS)");
        haystack[3_000..3_005].copy_from_slice(b"0aQRS");
        assert_eq!(haystack.as_ptr(), address);
        assert_eq!(regex.find_value(&haystack, SearchLimits::unlimited()).unwrap(), None);
        assert_eq!(
            other.find_value(&haystack, SearchLimits::unlimited()).unwrap(),
            Some(Match {
                start: 3_000,
                end: 3_005,
            }),
        );
    }

    #[test]
    fn reverse_suffix_span_accepts_a_match_starting_at_the_rejected_endpoint() {
        // The first suffix is not a match. The next match begins exactly at
        // that rejected endpoint, so the monotone floor is inclusive: no
        // source interval overlaps, and equality must remain eligible.
        let mut regex = forced_k0_with_bound_hir_mandatory_suffix(r"(?-u:[A-Z]{10}XYZ)");
        let PortablePlan::K0(plan) = &mut regex.plan else {
            unreachable!("fixture installs K0");
        };
        let suffix = plan.mandatory_suffix.as_mut().unwrap();
        suffix.recovery = K0MandatorySuffixRecoveryPlan::ReverseSuffixSpan(
            super::K0ReverseSuffixSpanAdaptiveState::new(),
        );
        let mut haystack = vec![b'!'; 4_096];
        haystack[2_000..2_003].copy_from_slice(b"XYZ");
        haystack[2_003..2_016].copy_from_slice(b"ABCDEFGHIJXYZ");
        let expected = Some(Match {
            start: 2_003,
            end: 2_016,
        });

        for window in [
            SearchWindow::full(&haystack),
            SearchWindow::new(1_500, haystack.len()),
        ] {
            let mut session = regex
                .search_session(SearchSessionLimits::unlimited())
                .unwrap();
            let PortableSearchSessionPlan::K0 {
                session: k0_session,
                mandatory_suffix: Some(suffix),
                ..
            } = &mut session.plan
            else {
                panic!("runtime fixture retains K0 suffix");
            };
            assert_eq!(
                try_execute_k0_reverse_suffix_span(
                    k0_session,
                    suffix,
                    &haystack,
                    window,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
                K0ReverseSuffixSpanAttempt::Complete(expected),
                "window={window:?}",
            );
            assert_eq!(
                session
                    .find_window_value(&haystack, window, SearchLimits::unlimited())
                    .unwrap(),
                expected,
                "authoritative window={window:?}",
            );
        }
    }

    fn forced_k0_with_structural_mandatory_suffix(pattern: &str) -> PortableRegex {
        let regex = forced_k0_with_bound_hir_mandatory_suffix(pattern);
        let PortablePlan::K0(plan) = &regex.plan else {
            unreachable!("bound-HIR helper always installs K0");
        };
        assert!(
            plan.mandatory_suffix
                .as_ref()
                .is_some_and(K0MandatorySuffixPlan::has_universal_finite_greedy_corridor),
        );
        regex
    }

    fn forced_k0_with_structural_suffix_and_negative_prefilter(
        pattern: &str,
    ) -> PortableRegex {
        let mut regex = forced_k0_with_structural_mandatory_suffix(pattern);
        let (_, hir, limits, _, minimum_match_bytes, _) =
            lowered_k0_mandatory_suffix_with_hir(pattern);
        let negative_prefilter = super::try_build_k0_negative_prefilter(
            &hir,
            minimum_match_bytes,
            limits,
            0,
            0,
            0,
            0,
        )
        .expect("focused independent-predicate analysis completes")
        .plan
        .expect("focused independent-predicate analysis retains a literal");
        let PortablePlan::K0(plan) = &mut regex.plan else {
            unreachable!("structural suffix helper always installs K0");
        };
        plan.negative_prefilter = Some(negative_prefilter);
        regex
    }

    #[test]
    fn k0_packed_frontier_owner_is_graph_bound_and_exactly_charged() {
        let (frontier, automaton, _, storage_bytes) =
            analyzed_k0_packed_frontier(r"(?s-u:...[abcd][12345]+\b)");
        let packed = frontier.packed.build_accounting();
        let overlap_bytes = frontier
            .maximum_before_root
            .checked_add(packed.max_pattern_bytes.saturating_sub(1))
            .unwrap();
        let unscaled_minimum = super::K0_PACKED_FRONTIER_MIN_WINDOW_BYTES
            .max(packed.simd_minimum_haystack_bytes)
            .max(
                overlap_bytes
                    .checked_mul(super::K0_PACKED_FRONTIER_OVERLAP_FACTOR)
                    .unwrap(),
            );
        assert!(frontier.is_bound_to(&automaton));
        assert!(frontier.maximum_before_root > 0);
        assert!(packed.patterns >= 2);
        assert_eq!(
            storage_bytes,
            core::mem::size_of::<K0PackedFrontierPlan>() + packed.persistent_bytes,
        );
        assert_eq!(frontier.storage_bytes(), storage_bytes);
        assert!(frontier.minimum_window_bytes >= packed.simd_minimum_haystack_bytes);
        assert!(frontier.minimum_window_bytes >= overlap_bytes);
        assert!(
            frontier.minimum_window_bytes >= super::K0_PACKED_FRONTIER_MIN_WINDOW_BYTES
        );
        assert_eq!(
            frontier.minimum_useful_progress_bytes(),
            super::K0_PACKED_FRONTIER_MIN_WINDOW_BYTES
                .max(packed.simd_minimum_haystack_bytes)
                .max(overlap_bytes),
        );
        assert!(frontier.minimum_window_bytes <= unscaled_minimum);
    }

    #[test]
    fn k0_packed_frontier_progress_threshold_is_exact() {
        let window_start = 41_usize;
        let witness_start = window_start + 3;
        let witness = super::K0PackedFrontierExactWitness {
            start: witness_start,
            bytes: u32::from_le_bytes([b'a', b'1', 0, 0]),
            length: 2,
        };
        let threshold = 1_024_usize;
        let positive = super::K0PackedFrontierPositiveObservation {
            residual_work: 17,
        };
        assert_eq!(
            super::classify_k0_packed_frontier_positive(
                window_start,
                witness,
                window_start,
                threshold,
                positive.residual_work,
            ),
            super::K0PackedFrontierObservation::ExactFloorDirect { witness },
        );
        assert_eq!(
            super::classify_k0_packed_frontier_positive(
                window_start,
                witness,
                window_start + threshold - 1,
                threshold,
                positive.residual_work,
            ),
            super::K0PackedFrontierObservation::ShallowCompletion(positive),
        );
        assert_eq!(
            super::classify_k0_packed_frontier_positive(
                window_start,
                witness,
                window_start + threshold,
                threshold,
                positive.residual_work,
            ),
            super::K0PackedFrontierObservation::ProductiveOrDeep,
        );
    }

    #[test]
    fn k0_packed_frontier_complexity_scaling_is_monotone_and_keeps_cheap_margins() {
        let baseline = u64::try_from(super::K0_PACKED_FRONTIER_MIN_WINDOW_BYTES).unwrap();
        let simd_minimum = 32_usize;
        let overlap = 257_usize;
        let four_overlaps = overlap
            .checked_mul(super::K0_PACKED_FRONTIER_OVERLAP_FACTOR)
            .unwrap();
        let minimum = |work| {
            super::k0_packed_frontier_minimum_window_bytes(
                simd_minimum,
                overlap,
                four_overlaps,
                work,
            )
        };

        // A cheap fallback, including the exact baseline-work boundary,
        // retains both original conservative margins. Thus an early positive
        // on a cheap graph never acquires new packed-frontier overhead.
        assert_eq!(super::k0_packed_frontier_amortization_scale(None), 1);
        assert_eq!(
            super::k0_packed_frontier_amortization_scale(Some(baseline - 1)),
            1,
        );
        assert_eq!(
            super::k0_packed_frontier_amortization_scale(Some(baseline)),
            1,
        );
        assert_eq!(minimum(None), four_overlaps);
        assert_eq!(minimum(Some(baseline - 1)), four_overlaps);
        assert_eq!(minimum(Some(baseline)), four_overlaps);

        // Crossing one complete structural-work unit lowers only the overlap
        // margin. Increasing immutable fallback cost can never cross the
        // universal 1 KiB admission floor.
        assert_eq!(
            super::k0_packed_frontier_amortization_scale(Some(baseline + 1)),
            2,
        );
        assert_eq!(minimum(Some(baseline + 1)), 1_024);
        assert_eq!(minimum(Some(baseline * 4)), 1_024);
        assert_eq!(minimum(Some(u64::MAX)), 1_024);
        let samples = [
            baseline - 1,
            baseline,
            baseline + 1,
            baseline * 2,
            baseline * 3,
            baseline * 4,
            u64::MAX,
        ];
        for pair in samples.windows(2) {
            assert!(minimum(Some(pair[1])) <= minimum(Some(pair[0])));
            assert!(minimum(Some(pair[1])) >= super::K0_PACKED_FRONTIER_MIN_WINDOW_BYTES);
        }
    }

    #[test]
    fn k0_packed_frontier_scaled_boundary_and_early_positive_remain_exact() {
        const PATTERN: &str = r"(?s-u:.{0,256}[abcd](?:XYZ|QRS|UVW|LMN)\b)";
        let regex = forced_k0_with_only_packed_frontier(PATTERN);
        let PortablePlan::K0(plan) = &regex.plan else {
            unreachable!();
        };
        let frontier = plan
            .packed_frontier()
            .expect("complexity-boundary fixture retains its packed frontier");
        let packed = frontier.packed.build_accounting();
        let overlap = frontier
            .maximum_before_root
            .checked_add(packed.max_pattern_bytes.saturating_sub(1))
            .unwrap();
        let four_overlaps = overlap
            .checked_mul(super::K0_PACKED_FRONTIER_OVERLAP_FACTOR)
            .unwrap();
        let incremental = super::k0_packed_frontier_incremental_fallback_work(
            &plan.automaton,
            packed.simd_minimum_haystack_bytes,
        )
        .expect("bounded fallback complexity fits its certified work type");
        assert!(
            super::k0_packed_frontier_amortization_scale(Some(incremental)) > 1,
            "the large bounded fallback must pay for a reduced margin",
        );
        assert_eq!(
            frontier.minimum_window_bytes,
            super::k0_packed_frontier_minimum_window_bytes(
                packed.simd_minimum_haystack_bytes,
                overlap,
                four_overlaps,
                Some(incremental),
            ),
        );
        assert!(frontier.minimum_window_bytes >= overlap);
        assert!(frontier.minimum_window_bytes >= packed.simd_minimum_haystack_bytes);
        assert_eq!(
            frontier.minimum_window_bytes,
            super::K0_PACKED_FRONTIER_MIN_WINDOW_BYTES,
            "structural scaling may reach but never cross the universal floor",
        );

        let window_start = 11_usize;
        let window_end = window_start
            .checked_add(frontier.minimum_window_bytes)
            .unwrap();
        let exact_window = SearchWindow::new(window_start, window_end);
        let one_below_window = SearchWindow::new(
            window_start,
            window_end.checked_sub(1).unwrap(),
        );
        let mut haystack = vec![b'!'; window_end + 7];
        haystack[window_start..window_start + 5].copy_from_slice(b"aXYZ!");

        let mut admission = regex
            .search_session(SearchSessionLimits::unlimited())
            .expect("boundary admission session constructs");
        {
            let PortableSearchSessionPlan::K0 {
                session,
                k0_plan,
                ..
            } = &mut admission.plan
            else {
                unreachable!();
            };
            assert!(
                K0PackedFrontierExistsReceipt::admit(
                    k0_plan,
                    session,
                    &haystack,
                    one_below_window,
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .is_none(),
            );
            assert!(
                K0PackedFrontierExistsReceipt::admit(
                    k0_plan,
                    session,
                    &haystack,
                    exact_window,
                    SearchLimits::unlimited(),
                )
                .unwrap()
                .is_some(),
            );
            assert!(
                K0PackedFrontierExistsReceipt::admit(
                    k0_plan,
                    session,
                    &haystack,
                    exact_window,
                    SearchLimits {
                        max_work: u64::MAX - 1,
                        max_scratch_bytes: usize::MAX,
                    },
                )
                .unwrap()
                .is_none(),
                "a scaled window must not bypass an exact finite K0 limit",
            );
        }

        let mut authoritative = regex
            .search_session(SearchSessionLimits::unlimited())
            .expect("authoritative small-window session constructs");
        let mut specialized = regex
            .search_session(SearchSessionLimits::unlimited())
            .expect("specialized small-window session constructs");
        let expected = authoritative
            .is_match_window(&haystack, exact_window, SearchLimits::unlimited())
            .unwrap()
            .0;
        assert!(expected);
        assert_eq!(
            specialized
                .is_match_window_value(
                    &haystack,
                    exact_window,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            expected,
        );

        // A retained Direct epoch never retains a result or source cursor:
        // identical storage mutated to absence is searched again exactly.
        let address = haystack.as_ptr();
        haystack.fill(b'!');
        assert_eq!(haystack.as_ptr(), address);
        let expected = authoritative
            .is_match_window(&haystack, exact_window, SearchLimits::unlimited())
            .unwrap()
            .0;
        assert!(!expected);
        assert_eq!(
            specialized
                .is_match_window_value(
                    &haystack,
                    exact_window,
                    SearchLimits::unlimited(),
                )
                .unwrap(),
            expected,
        );
    }

