    #[test]
    fn staged_vector_general_primaries_route_before_k0_but_direct_and_raw_preserve_k0() {
        let limits = BuildLimits {
            literal_set: fre_kernels::LiteralSetBuildLimits {
                max_patterns: 4,
                ..fre_kernels::LiteralSetBuildLimits::default()
            },
            ..BuildLimits::default()
        };
        let paired = PortableBuilder::new("[a-c][d-f]")
            .unicode(false)
            .limits(limits)
            .build()
            .unwrap();
        assert_eq!(paired.build_report().plan, PlanKind::FixedPredicateWord64);
        let (matched, accounting) = paired
            .find(b"xxbe", SearchLimits::unlimited())
            .unwrap();
        assert_eq!(matched, Some(Match { start: 2, end: 4 }));
        let SearchAccounting::FixedPredicateWord64(accounting) = accounting else {
            panic!("selective general pair lost its fixed-predicate accounting")
        };
        assert_eq!(
            accounting.identity.reducer,
            FixedPredicateWord64Reducer::ShiftAnd
        );
        assert_eq!(
            accounting.identity.primary_finder.unwrap().kind,
            FixedPredicateWord64AdaptiveFinderKind::Three
        );
        assert!(matches!(
            accounting.identity.adaptive_handoff,
            FixedPredicateWord64AdaptiveHandoffIdentity::Finder { .. }
        ));

        const RANGE_LEFT: &[(u8, u8)] = &[(b'a', b'd')];
        const RANGE_RIGHT: &[(u8, u8)] = &[(b'e', b'h')];
        const FOUR_LEFT: &[(u8, u8)] = &[
            (b'B', b'B'),
            (b'D', b'D'),
            (b'F', b'F'),
            (b'H', b'H'),
        ];
        const FOUR_RIGHT: &[(u8, u8)] = &[
            (b'J', b'J'),
            (b'L', b'L'),
            (b'N', b'N'),
            (b'P', b'P'),
        ];
        const SET_LEFT: &[(u8, u8)] = &[(b'A', b'C'), (b'F', b'F'), (b'H', b'H')];
        const SET_RIGHT: &[(u8, u8)] =
            &[(b'J', b'L'), (b'N', b'N'), (b'P', b'P'), (b'R', b'R')];
        const HIGH_RANGE_LEFT: &[(u8, u8)] = &[(0x80, 0x83)];
        const HIGH_RANGE_RIGHT: &[(u8, u8)] = &[(0x90, 0x93)];
        const HIGH_FOUR_LEFT: &[(u8, u8)] =
            &[(0x80, 0x80), (0x82, 0x82), (0x84, 0x84), (0x86, 0x86)];
        const HIGH_FOUR_RIGHT: &[(u8, u8)] = &[
            (0x91, 0x91),
            (0x93, 0x93),
            (0x95, 0x95),
            (0x97, 0x98),
        ];
        const HIGH_SET_LEFT: &[(u8, u8)] =
            &[(0x80, 0x81), (0x84, 0x84), (0x88, 0x89)];
        const HIGH_SET_RIGHT: &[(u8, u8)] =
            &[(0x90, 0x92), (0x95, 0x95), (0x98, 0x98), (0x9A, 0x9A)];
        for (pattern, haystack, primary_kind, predicates) in [
            (
                r"[a-d][e-h]",
                &b"\xff\xffaf"[..],
                Some(FixedPredicateWord64AdaptiveFinderKind::Range),
                &[RANGE_LEFT, RANGE_RIGHT][..],
            ),
            (
                r"[BDFH][JLNP]",
                &b"\xff\xffBJ"[..],
                Some(FixedPredicateWord64AdaptiveFinderKind::Four),
                &[FOUR_LEFT, FOUR_RIGHT][..],
            ),
            (
                r"[A-CFH][J-LNPR]",
                &b"\xff\xffAJ"[..],
                Some(FixedPredicateWord64AdaptiveFinderKind::Set),
                &[SET_LEFT, SET_RIGHT][..],
            ),
            (
                r"[\x80-\x83][\x90-\x93]",
                &b"\xff\xff\x80\x90"[..],
                Some(FixedPredicateWord64AdaptiveFinderKind::Range),
                &[HIGH_RANGE_LEFT, HIGH_RANGE_RIGHT][..],
            ),
            (
                r"[\x80\x82\x84\x86][\x91\x93\x95\x97-\x98]",
                &b"\xff\xff\x80\x91"[..],
                Some(FixedPredicateWord64AdaptiveFinderKind::Four),
                &[HIGH_FOUR_LEFT, HIGH_FOUR_RIGHT][..],
            ),
            (
                r"[\x80-\x81\x84\x88-\x89][\x90-\x92\x95\x98\x9A]",
                &b"\xff\xff\x80\x90"[..],
                Some(FixedPredicateWord64AdaptiveFinderKind::Set),
                &[HIGH_SET_LEFT, HIGH_SET_RIGHT][..],
            ),
        ] {
            let low_level = fre_kernels::FixedPredicateWord64Plan::build(
                predicates,
                fre_kernels::FixedPredicateWord64BuildLimits::unlimited(),
            )
            .unwrap();
            let expected_fixed = matches!(
                low_level.general_primary_scan_identity(),
                Some(FixedPredicateWord64GeneralPrimaryScanIdentity::Memchr3)
                    | Some(FixedPredicateWord64GeneralPrimaryScanIdentity::CompiledWholeSlice)
            );
            let fixed = PortableBuilder::new(pattern)
                .unicode(false)
                .limits(limits)
                .build()
                .unwrap();
            assert_eq!(
                fixed.build_report().plan,
                if expected_fixed {
                    PlanKind::FixedPredicateWord64
                } else {
                    PlanKind::K0
                },
                "pattern={pattern}"
            );
            let (matched, accounting) = fixed
                .find(haystack, SearchLimits::unlimited())
                .unwrap();
            assert_eq!(matched, Some(Match { start: 2, end: 4 }));
            match accounting {
                SearchAccounting::FixedPredicateWord64(accounting) => {
                    assert_eq!(
                        accounting.identity.reducer,
                        FixedPredicateWord64Reducer::ShiftAnd
                    );
                    assert_eq!(
                        accounting.identity.primary_finder.map(|finder| finder.kind),
                        primary_kind,
                        "pattern={pattern}"
                    );
                }
                SearchAccounting::K0(_) if !expected_fixed => {}
                other => panic!(
                    "generalized Shift-And route has unexpected accounting for {pattern}: {other:?}"
                ),
            }
        }

        for (pattern, haystack) in [
            (r"[\x00-\x7E][\x00-\x7E]", &b"\xff\xffAA"[..]),
            (r"[a-c][\x00-\xFF]", &b"\xff\xffa\xff"[..]),
        ] {
            let k0 = PortableBuilder::new(pattern)
                .unicode(false)
                .limits(limits)
                .build()
                .unwrap();
            assert_eq!(k0.build_report().plan, PlanKind::K0, "pattern={pattern}");
            assert_eq!(
                k0.find(haystack, SearchLimits::unlimited()).unwrap().0,
                Some(Match { start: 2, end: 4 }),
                "pattern={pattern}"
            );
        }
    }

    #[test]
    fn fixed_predicate_iterators_retain_candidates_and_reset_after_early_drop() {
        let limits = BuildLimits {
            literal_set: fre_kernels::LiteralSetBuildLimits {
                max_patterns: 4,
                ..fre_kernels::LiteralSetBuildLimits::default()
            },
            ..BuildLimits::default()
        };
        let regex = PortableBuilder::new(r"[A-D][\x00-\x7F]Q")
            .unicode(false)
            .limits(limits)
            .build()
            .unwrap();
        assert_eq!(regex.build_report().plan, PlanKind::FixedPredicateWord64);

        let mut haystack = Vec::new();
        for _ in 0..8 {
            haystack.extend_from_slice(&[0xff, b'!', b'Q']);
        }
        for _ in 0..64 {
            haystack.extend_from_slice(b"A!Q");
        }
        let expected_first = Match { start: 24, end: 27 };

        let mut early = regex
            .find_iter(&haystack, PortableFindIterLimits::unlimited())
            .unwrap();
        assert!(early.state.is_fixed_predicate());
        assert_eq!(early.next().unwrap().unwrap(), expected_first);
        drop(early);
        let mut restarted = regex
            .find_iter(&haystack, PortableFindIterLimits::unlimited())
            .unwrap();
        assert!(restarted.state.is_fixed_predicate());
        assert_eq!(restarted.next().unwrap().unwrap(), expected_first);
        assert_eq!(restarted.count(), 63);

        let mut session = regex
            .search_session(SearchSessionLimits::unlimited())
            .unwrap();
        let mut session_matches =
            session.find_iter(&haystack, PortableFindIterRunLimits::unlimited());
        assert!(session_matches.state.is_fixed_predicate());
        let matches = session_matches
            .by_ref()
            .collect::<Result<Vec<_>, _>>()
            .unwrap();
        drop(session_matches);
        assert_eq!(matches.len(), 64);
        assert_eq!(matches[0], expected_first);
        assert!(
            matches
                .windows(2)
                .all(|pair| pair[0].end() == pair[1].start())
        );

        let exact = PortableBuilder::new("literal")
            .unicode(false)
            .build()
            .unwrap();
        let exact_iter = exact
            .find_iter(b"literal", PortableFindIterLimits::unlimited())
            .unwrap();
        assert!(!exact_iter.state.is_fixed_predicate());
    }

    #[test]
    fn fixed_predicate_construction_failure_checks_receipt_closure_before_divergence() {
        let source = include_str!("lib.rs");
        let start = source
            .find("let attempt = match FixedPredicateWord64Plan::build_attempt(")
            .expect("fixed-predicate construction match remains explicit");
        let end = source[start..]
            .find("if !attempt.closes()")
            .expect("successful construction closure check remains explicit");
        let construction_match = &source[start..start + end];
        assert!(construction_match.contains("Err(error) =>"));
        assert!(construction_match.contains("if !error.closes()"));
        assert!(
            construction_match
                .contains("fixed-predicate search construction failure lost its attempt closure")
        );
        assert!(
            construction_match
                .contains("inspected fixed-predicate search source failed kernel construction")
        );
    }

    #[test]
    fn k0_session_retains_a_general_ascii_root_classifier() {
        let pattern = r"([0-9][0-9]?)/([0-9][0-9]?)/([0-9][0-9]([0-9][0-9])?)";
        let fre = PortableBuilder::new(pattern)
            .unicode(false)
            .build()
            .expect("bounded date shape belongs to portable K0");
        assert_eq!(fre.build_report().plan, PlanKind::K0);
        let upstream = regex::bytes::RegexBuilder::new(pattern)
            .unicode(false)
            .build()
            .unwrap();
        let mut session = fre
            .search_session(super::SearchSessionLimits::unlimited())
            .unwrap();

        let mut haystack = vec![b'x'; 4_096];
        haystack.extend_from_slice(b" 1/2/2024 tail");
        let expected = upstream
            .find(&haystack)
            .map(|matched| (matched.start(), matched.end()));
        let (actual, accounting) = session.find(&haystack, SearchLimits::unlimited()).unwrap();
        assert_eq!(
            actual.map(|matched| (matched.start(), matched.end())),
            expected
        );
        let SearchAccounting::K0(accounting) = accounting else {
            panic!("date shape should report K0 accounting");
        };
        assert!(accounting.boundaries() < 32);
    }

